INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-11', 'ngsl-1', 'Thông dụng 1–500 · Bộ 11', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 1, 'reach', 'đến, tới; đạt được; với tới', 'verb', '[{"en":"We reached the hotel just before midnight.","vi":"Chúng tôi đến khách sạn ngay trước nửa đêm."},{"en":"The two sides finally reached an agreement after long talks.","vi":"Sau những cuộc đàm phán kéo dài, hai bên cuối cùng đã đạt được thỏa thuận."},{"en":"Can you reach the top shelf for me?","vi":"Bạn với tới cái kệ trên cùng giúp tôi được không?"}]', '[{"phrase":"reach an agreement"},{"phrase":"reach a decision"},{"phrase":"reach the top"}]', NULL, '/riːtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reach/reach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 2, 'social', '(thuộc) xã hội; giao tiếp, giao du', 'adjective', '[{"en":"Social media has changed the way young people communicate.","vi":"Mạng xã hội đã thay đổi cách giới trẻ giao tiếp."},{"en":"Poverty is one of the biggest social problems in the city.","vi":"Nghèo đói là một trong những vấn đề xã hội lớn nhất của thành phố."},{"en":"She has a busy social life and goes out most weekends.","vi":"Cô ấy có cuộc sống giao du bận rộn và hầu như cuối tuần nào cũng ra ngoài."}]', '[{"phrase":"social media"},{"phrase":"social life"},{"phrase":"social problem"},{"phrase":"social skills"}]', NULL, '/ˈsəʊʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soc/socia/social__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 3, 'period', 'giai đoạn, thời kỳ; khoảng thời gian; tiết học', 'noun', '[{"en":"He lived in France for a short period after college.","vi":"Anh ấy sống ở Pháp một thời gian ngắn sau khi học xong đại học."},{"en":"The store is closed during the holiday period.","vi":"Cửa hàng đóng cửa trong thời gian nghỉ lễ."},{"en":"We have math in the first period on Tuesdays.","vi":"Vào thứ Ba, chúng tôi học toán tiết đầu tiên."}]', '[{"phrase":"a period of time"},{"phrase":"a short period"},{"phrase":"the holiday period"},{"phrase":"trial period"}]', NULL, '/ˈpɪriəd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perio/period__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 4, 'across', 'qua, băng qua; ở bên kia; khắp', 'preposition', '[{"en":"Be careful when you walk across the street.","vi":"Hãy cẩn thận khi bạn đi bộ qua đường."},{"en":"There is a small café across the road from our office.","vi":"Có một quán cà phê nhỏ ở bên kia đường, đối diện văn phòng chúng tôi."},{"en":"The company has stores across the country.","vi":"Công ty có cửa hàng trên khắp cả nước."}]', '[{"phrase":"across the street"},{"phrase":"across the road"},{"phrase":"across the country"},{"phrase":"walk across"}]', NULL, '/əˈkrɔːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acr/acros/across__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 5, 'note', 'ghi chú; lời nhắn, mẩu giấy nhắn', 'noun', '[{"en":"I took notes during the lecture so I could review them later.","vi":"Tôi ghi chép trong buổi giảng để có thể ôn lại sau."},{"en":"She left a note on the fridge saying she''d be late.","vi":"Cô ấy để lại mẩu giấy nhắn trên tủ lạnh, báo rằng sẽ về muộn."},{"en":"Please make a note of the meeting time.","vi":"Bạn hãy ghi lại giờ họp nhé."}]', '[{"phrase":"take notes"},{"phrase":"leave a note"},{"phrase":"make a note of"}]', NULL, '/nəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/note_/note__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 6, 'history', 'lịch sử; tiền sử, quá trình', 'noun', '[{"en":"History was my favorite subject in high school.","vi":"Lịch sử là môn học yêu thích của tôi hồi cấp ba."},{"en":"This town has a long and interesting history.","vi":"Thị trấn này có một lịch sử lâu đời và thú vị."},{"en":"The doctor asked about my family''s medical history.","vi":"Bác sĩ hỏi về tiền sử bệnh của gia đình tôi."}]', '[{"phrase":"long history"},{"phrase":"medical history"},{"phrase":"history lesson"}]', NULL, '/ˈhɪstri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/history__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 7, 'create', 'tạo ra; sáng tạo', 'verb', '[{"en":"The new factory will create hundreds of jobs.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm."},{"en":"You need to create a password for your account.","vi":"Bạn cần tạo mật khẩu cho tài khoản của mình."},{"en":"The children created beautiful paintings in art class.","vi":"Trong giờ mỹ thuật, bọn trẻ đã sáng tạo nên những bức tranh thật đẹp."}]', '[{"phrase":"create jobs"},{"phrase":"create an account"},{"phrase":"create problems"},{"phrase":"create opportunities"}]', NULL, '/kriˈeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/create__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 8, 'drive', 'lái (xe); chở (ai) bằng xe', 'verb', '[{"en":"My father drives to work every morning.","vi":"Bố tôi lái xe đi làm mỗi sáng."},{"en":"Can you drive me to the airport tomorrow?","vi":"Ngày mai bạn chở tôi ra sân bay được không?"},{"en":"She learned to drive when she was eighteen.","vi":"Cô ấy học lái xe khi mười tám tuổi."}]', '[{"phrase":"drive a car"},{"phrase":"drive to work"},{"phrase":"learn to drive"}]', 'drive – drove – driven', '/draɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drive/drive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 9, 'along', 'dọc theo', 'preposition', '[{"en":"We walked along the beach at sunset.","vi":"Chúng tôi đi dạo dọc bãi biển lúc hoàng hôn."},{"en":"There are many small shops along this street.","vi":"Có nhiều cửa hàng nhỏ dọc con phố này."},{"en":"Trees were planted along both sides of the river.","vi":"Cây được trồng dọc hai bên bờ sông."}]', '[{"phrase":"walk along"},{"phrase":"along the road"},{"phrase":"along the river"},{"phrase":"along the beach"}]', NULL, '/əˈlɔːŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/along/along__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 10, 'type', 'loại, kiểu', 'noun', '[{"en":"What type of music do you like?","vi":"Bạn thích loại nhạc nào?"},{"en":"This type of plant needs a lot of sunlight.","vi":"Loại cây này cần nhiều ánh nắng."},{"en":"He''s not the type of person who gives up easily.","vi":"Anh ấy không phải kiểu người dễ bỏ cuộc."}]', '[{"phrase":"type of person"},{"phrase":"blood type"},{"phrase":"different types"}]', NULL, '/taɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/type_/type__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 11, 'sound', 'âm thanh, tiếng, tiếng động', 'noun', '[{"en":"I heard a strange sound coming from the kitchen.","vi":"Tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"Please turn the sound down because the baby is sleeping.","vi":"Làm ơn vặn nhỏ tiếng xuống vì em bé đang ngủ."},{"en":"I love the sound of rain on the roof.","vi":"Tôi thích tiếng mưa rơi trên mái nhà."}]', '[{"phrase":"make a sound"},{"phrase":"strange sound"},{"phrase":"loud sound"},{"phrase":"the sound of"}]', NULL, '/saʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sound/sound__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 12, 'eye', 'mắt', 'noun', '[{"en":"She has beautiful blue eyes, just like her mother.","vi":"Cô ấy có đôi mắt xanh rất đẹp, giống hệt mẹ mình."},{"en":"Close your eyes and try to relax.","vi":"Hãy nhắm mắt lại và cố gắng thư giãn."},{"en":"My eyes hurt after looking at the screen all day.","vi":"Mắt tôi bị đau sau khi nhìn màn hình cả ngày."}]', '[{"phrase":"close your eyes"},{"phrase":"open your eyes"},{"phrase":"blue eyes"},{"phrase":"keep an eye on"}]', NULL, '/aɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eye/eye__/eye__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 13, 'music', 'âm nhạc, nhạc', 'noun', '[{"en":"I often listen to music while I study.","vi":"Tôi thường nghe nhạc trong lúc học bài."},{"en":"The music at the party was too loud.","vi":"Nhạc ở bữa tiệc quá to."},{"en":"He wants to study music at university.","vi":"Anh ấy muốn học âm nhạc ở đại học."}]', '[{"phrase":"listen to music"},{"phrase":"play music"},{"phrase":"loud music"},{"phrase":"music lesson"}]', 'không đếm được', '/ˈmjuːzɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/music__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 14, 'game', 'trò chơi; trận đấu', 'noun', '[{"en":"The kids played a board game after dinner.","vi":"Bọn trẻ chơi một trò chơi cờ bàn sau bữa tối."},{"en":"Did you watch the basketball game last night?","vi":"Tối qua bạn có xem trận bóng rổ không?"},{"en":"My brother spends too much time playing video games.","vi":"Em trai tôi dành quá nhiều thời gian chơi trò chơi điện tử."}]', '[{"phrase":"play a game"},{"phrase":"video game"},{"phrase":"board game"},{"phrase":"win the game"}]', NULL, '/ɡeɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gam/game_/game__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 15, 'political', '(thuộc) chính trị', 'adjective', '[{"en":"The country has two main political parties.","vi":"Đất nước này có hai đảng chính trị chính."},{"en":"They avoid political topics at family dinners.","vi":"Họ tránh các chủ đề chính trị trong những bữa ăn gia đình."},{"en":"She is studying political science at university.","vi":"Cô ấy đang học ngành khoa học chính trị ở đại học."}]', '[{"phrase":"political party"},{"phrase":"political science"},{"phrase":"political issue"},{"phrase":"political system"}]', NULL, '/pəˈlɪtɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/political__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 16, 'free', 'miễn phí; rảnh; tự do', 'adjective', '[{"en":"Entry to the museum is free on Sundays.","vi":"Vào bảo tàng được miễn phí vào các ngày Chủ nhật."},{"en":"Are you free to have lunch with me tomorrow?","vi":"Ngày mai bạn có rảnh đi ăn trưa với tôi không?"},{"en":"The bird was finally set free from its cage.","vi":"Con chim cuối cùng cũng được thả tự do khỏi lồng."}]', '[{"phrase":"free time"},{"phrase":"for free"},{"phrase":"free of charge"},{"phrase":"feel free"}]', NULL, '/friː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/free_/free__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 17, 'receive', 'nhận, nhận được', 'verb', '[{"en":"Did you receive my email this morning?","vi":"Sáng nay bạn có nhận được email của tôi không?"},{"en":"She received a lot of gifts on her birthday.","vi":"Cô ấy nhận được rất nhiều quà vào ngày sinh nhật."},{"en":"He received an award for his hard work.","vi":"Anh ấy nhận được giải thưởng nhờ sự làm việc chăm chỉ."}]', '[{"phrase":"receive a letter"},{"phrase":"receive an email"},{"phrase":"receive an award"},{"phrase":"receive help"}]', NULL, '/rɪˈsiːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recei/receive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 18, 'moment', 'lúc, khoảnh khắc; chốc lát', 'noun', '[{"en":"Please wait a moment while I check your booking.","vi":"Xin vui lòng đợi một chút trong khi tôi kiểm tra đặt chỗ của bạn."},{"en":"She is busy at the moment, so please call back later.","vi":"Hiện giờ cô ấy đang bận, nên vui lòng gọi lại sau."},{"en":"Winning the race was the best moment of my life.","vi":"Chiến thắng cuộc đua là khoảnh khắc tuyệt vời nhất trong đời tôi."}]', '[{"phrase":"at the moment"},{"phrase":"wait a moment"},{"phrase":"for a moment"},{"phrase":"the right moment"}]', NULL, '/ˈməʊmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mom/momen/moment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 19, 'sale', 'sự bán; đợt giảm giá; doanh số (sales)', 'noun', '[{"en":"The house next to ours is for sale.","vi":"Căn nhà bên cạnh nhà chúng tôi đang được rao bán."},{"en":"The store is having a big sale this weekend.","vi":"Cuối tuần này cửa hàng có đợt giảm giá lớn."},{"en":"Sales of electric bikes have grown quickly this year.","vi":"Doanh số xe đạp điện đã tăng nhanh trong năm nay."}]', '[{"phrase":"for sale"},{"phrase":"on sale"},{"phrase":"big sale"},{"phrase":"sales figures"}]', NULL, '/seɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/sale_/sale__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 20, 'policy', 'chính sách; quy định', 'noun', '[{"en":"The company has a strict policy on working from home.","vi":"Công ty có quy định nghiêm ngặt về việc làm việc tại nhà."},{"en":"Our school has a no-phone policy during class.","vi":"Trường chúng tôi có quy định cấm dùng điện thoại trong giờ học."},{"en":"The government announced a new policy to support small businesses.","vi":"Chính phủ đã công bố một chính sách mới để hỗ trợ các doanh nghiệp nhỏ."}]', '[{"phrase":"company policy"},{"phrase":"government policy"},{"phrase":"return policy"},{"phrase":"strict policy"}]', NULL, '/ˈpɑːləsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/policy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 21, 'further', 'xa hơn; thêm, hơn nữa', 'adverb', '[{"en":"The hotel was further from the beach than we expected.","vi":"Khách sạn cách bãi biển xa hơn chúng tôi nghĩ."},{"en":"I''m too tired to walk any further.","vi":"Tôi mệt quá, không thể đi xa hơn được nữa."},{"en":"We decided not to discuss the matter any further.","vi":"Chúng tôi quyết định không bàn thêm về vấn đề này nữa."}]', '[{"phrase":"any further"},{"phrase":"go further"},{"phrase":"further information"}]', 'far – further – furthest', '/ˈfɜːrðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/further__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 22, 'body', 'cơ thể; thân thể', 'noun', '[{"en":"Regular exercise keeps your body strong and healthy.","vi":"Tập thể dục đều đặn giúp cơ thể bạn khỏe mạnh."},{"en":"My whole body ached after the long hike.","vi":"Toàn thân tôi đau nhức sau chuyến đi bộ đường dài."},{"en":"Water makes up about sixty percent of the human body.","vi":"Nước chiếm khoảng sáu mươi phần trăm cơ thể người."}]', '[{"phrase":"human body"},{"phrase":"whole body"},{"phrase":"body temperature"},{"phrase":"body language"}]', NULL, '/ˈbɑːdi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bod/body_/body__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 23, 'require', 'đòi hỏi, cần; yêu cầu', 'verb', '[{"en":"This job requires good communication skills and some experience.","vi":"Công việc này đòi hỏi kỹ năng giao tiếp tốt và một chút kinh nghiệm."},{"en":"All visitors are required to sign in at the front desk.","vi":"Tất cả khách đến thăm đều được yêu cầu đăng ký tại quầy lễ tân."},{"en":"Most houseplants require very little care.","vi":"Hầu hết các loại cây trồng trong nhà cần rất ít công chăm sóc."}]', '[{"phrase":"be required to"},{"phrase":"require skills"},{"phrase":"require attention"}]', NULL, '/rɪˈkwaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/require__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 24, 'wait', 'chờ, đợi', 'verb', '[{"en":"Please wait here until your name is called.","vi":"Vui lòng đợi ở đây cho đến khi được gọi tên."},{"en":"We waited for the bus for almost an hour.","vi":"Chúng tôi đã chờ xe buýt gần một tiếng."},{"en":"I can''t wait to see you again next month.","vi":"Tôi nóng lòng chờ được gặp lại bạn vào tháng sau."}]', '[{"phrase":"wait for"},{"phrase":"wait a minute"},{"phrase":"can''t wait"},{"phrase":"wait in line"}]', 'wait for sb/sth: chờ ai/cái gì', '/weɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wai/wait_/wait__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 25, 'general', 'chung; tổng quát', 'adjective', '[{"en":"In general, people here are very friendly.","vi":"Nhìn chung, người dân ở đây rất thân thiện."},{"en":"The book gives a general introduction to world history.","vi":"Cuốn sách giới thiệu tổng quát về lịch sử thế giới."},{"en":"Can you give me a general idea of the cost?","vi":"Bạn có thể cho tôi biết sơ qua về chi phí không?"}]', '[{"phrase":"in general"},{"phrase":"general idea"},{"phrase":"general public"},{"phrase":"general knowledge"}]', NULL, '/ˈdʒenrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/general__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 26, 'appear', 'xuất hiện; có vẻ', 'verb', '[{"en":"A strange man suddenly appeared at the door.","vi":"Một người đàn ông lạ bỗng xuất hiện ở cửa."},{"en":"She appeared very nervous before her speech.","vi":"Cô ấy có vẻ rất lo lắng trước bài phát biểu."},{"en":"Her photo appeared in the local newspaper last week.","vi":"Ảnh của cô ấy xuất hiện trên tờ báo địa phương tuần trước."}]', '[{"phrase":"suddenly appear"},{"phrase":"appear to be"},{"phrase":"appear on television"}]', NULL, '/əˈpɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appear__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 27, 'toward', 'về phía; đối với', 'preposition', '[{"en":"The dog ran toward me, wagging its tail.","vi":"Con chó vừa chạy về phía tôi vừa vẫy đuôi."},{"en":"She walked toward the door without saying a word.","vi":"Cô ấy đi về phía cửa mà không nói một lời."},{"en":"His attitude toward his work has improved a lot.","vi":"Thái độ của anh ấy đối với công việc đã tiến bộ nhiều."}]', '[{"phrase":"walk toward"},{"phrase":"attitude toward"},{"phrase":"toward the end"}]', 'Mỹ: toward · Anh: towards', '/təˈwɔrd/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 28, 'team', 'đội, nhóm', 'noun', '[{"en":"Our team won the match by two goals.","vi":"Đội chúng tôi thắng trận với cách biệt hai bàn."},{"en":"She works in a small team of designers.","vi":"Cô ấy làm việc trong một nhóm nhỏ gồm các nhà thiết kế."},{"en":"Do you want to join the school football team?","vi":"Bạn có muốn tham gia đội bóng đá của trường không?"}]', '[{"phrase":"football team"},{"phrase":"join a team"},{"phrase":"team member"},{"phrase":"work as a team"}]', NULL, '/tiːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/team_/team__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 29, 'easy', 'dễ, dễ dàng', 'adjective', '[{"en":"The test was easier than I expected.","vi":"Bài kiểm tra dễ hơn tôi nghĩ."},{"en":"It isn''t easy to learn a new language.","vi":"Học một ngôn ngữ mới không hề dễ."},{"en":"This recipe is quick and easy to follow.","vi":"Công thức này nhanh gọn và dễ làm theo."}]', '[{"phrase":"easy to use"},{"phrase":"easy question"},{"phrase":"take it easy"},{"phrase":"easy way"}]', 'easy – easier – easiest', '/ˈiːzi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easy_/easy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-11', 30, 'individual', 'riêng, cá nhân; từng (người, cái)', 'adjective', '[{"en":"Each student receives individual attention from the teacher.","vi":"Mỗi học sinh đều được giáo viên quan tâm riêng."},{"en":"We try to meet the individual needs of every customer.","vi":"Chúng tôi cố gắng đáp ứng nhu cầu riêng của từng khách hàng."},{"en":"The price of each individual item is shown on the label.","vi":"Giá của từng món hàng được ghi trên nhãn."}]', '[{"phrase":"individual needs"},{"phrase":"individual attention"},{"phrase":"individual differences"}]', NULL, '/ˌɪndɪˈvɪdʒuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indiv/individual__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-12', 'ngsl-1', 'Thông dụng 1–500 · Bộ 12', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 12);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 1, 'full', 'đầy; no', 'adjective', '[{"en":"The bus was so full that we had to stand.","vi":"Xe buýt chật kín người đến mức chúng tôi phải đứng."},{"en":"No more water for me, please. My glass is still full.","vi":"Đừng rót thêm nước cho tôi nhé. Cốc của tôi vẫn còn đầy."},{"en":"No more rice for me, thanks. I''m really full.","vi":"Tôi không ăn thêm cơm nữa đâu, cảm ơn. Tôi no lắm rồi."}]', '[{"phrase":"full of"},{"phrase":"completely full"},{"phrase":"full name"},{"phrase":"full time"}]', 'be full of: đầy thứ gì', '/fʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/ful/full_/full__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 2, 'black', 'đen; (cà phê) không sữa', 'adjective', '[{"en":"He always wears a black jacket to work.","vi":"Anh ấy luôn mặc áo khoác đen đi làm."},{"en":"I drink my coffee black, without sugar.","vi":"Tôi uống cà phê đen, không đường."},{"en":"Her cat is completely black except for its white paws.","vi":"Con mèo của cô ấy đen tuyền, chỉ có bàn chân màu trắng."}]', '[{"phrase":"black coffee"},{"phrase":"black hair"},{"phrase":"black and white"}]', NULL, '/blæk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bla/black/black__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 3, 'sense', 'ý nghĩa; cảm giác; giác quan', 'noun', '[{"en":"His explanation doesn''t make any sense to me.","vi":"Lời giải thích của anh ấy chẳng có nghĩa lý gì với tôi."},{"en":"Finishing the project gave her a real sense of pride.","vi":"Hoàn thành dự án mang lại cho cô ấy cảm giác thực sự tự hào."},{"en":"Dogs have a much better sense of smell than people.","vi":"Chó có khứu giác tốt hơn con người rất nhiều."}]', '[{"phrase":"make sense"},{"phrase":"sense of humor"},{"phrase":"sense of smell"},{"phrase":"common sense"}]', 'make sense: hợp lý, dễ hiểu', '/sens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sense/sense__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 4, 'perhaps', 'có lẽ; có thể', 'adverb', '[{"en":"Perhaps we should leave early to avoid the traffic.","vi":"Có lẽ chúng ta nên đi sớm để tránh kẹt xe."},{"en":"She hasn''t called yet; perhaps she''s still at work.","vi":"Cô ấy vẫn chưa gọi; có lẽ cô ấy vẫn đang ở chỗ làm."},{"en":"The trip will take three hours, perhaps a little more.","vi":"Chuyến đi sẽ mất ba tiếng, có thể hơn một chút."}]', '[{"phrase":"perhaps not"},{"phrase":"or perhaps"},{"phrase":"perhaps even"}]', NULL, '/pərˈhæps/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perha/perhaps__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 5, 'add', 'thêm; cộng; nói thêm', 'verb', '[{"en":"Add a little salt to the soup before serving.","vi":"Thêm một chút muối vào canh trước khi dọn ra."},{"en":"If you add five and seven, you get twelve.","vi":"Nếu cộng năm với bảy, bạn được mười hai."},{"en":"\"And please don''t be late again,\" my boss added.","vi":"\"Và làm ơn đừng đến muộn nữa,\" sếp tôi nói thêm."}]', '[{"phrase":"add salt"},{"phrase":"add to"},{"phrase":"add up"},{"phrase":"add a comment"}]', 'add A to B: thêm A vào B', '/æd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/add__/add__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 6, 'rule', 'quy tắc; luật lệ', 'noun', '[{"en":"Can you explain the rules of the game to me?","vi":"Bạn có thể giải thích luật chơi cho tôi không?"},{"en":"Students must follow the school rules at all times.","vi":"Học sinh phải luôn tuân thủ nội quy của trường."},{"en":"As a rule, I don''t check emails on weekends.","vi":"Thường thì tôi không kiểm tra email vào cuối tuần."}]', '[{"phrase":"follow the rules"},{"phrase":"break the rules"},{"phrase":"as a rule"},{"phrase":"strict rules"}]', NULL, '/ruːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rul/rule_/rule__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 7, 'pass', 'đi qua; vượt qua (kỳ thi); đưa, chuyền', 'verb', '[{"en":"We passed a small café on the way to the station.","vi":"Trên đường ra ga, chúng tôi đi ngang qua một quán cà phê nhỏ."},{"en":"She studied hard and passed her driving test.","vi":"Cô ấy học chăm chỉ và đã thi đỗ bằng lái xe."},{"en":"Could you pass me the salt, please?","vi":"Bạn đưa giúp tôi lọ muối được không?"}]', '[{"phrase":"pass an exam"},{"phrase":"pass a test"},{"phrase":"pass the salt"},{"phrase":"time passes"}]', NULL, '/pæs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/pass_/pass__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 8, 'produce', 'sản xuất; tạo ra', 'verb', '[{"en":"This factory produces over a thousand cars a week.","vi":"Nhà máy này sản xuất hơn một nghìn chiếc ô tô mỗi tuần."},{"en":"The region produces most of the country''s coffee.","vi":"Vùng này sản xuất phần lớn cà phê của cả nước."},{"en":"Our new plan has already produced good results.","vi":"Kế hoạch mới của chúng tôi đã tạo ra kết quả tốt."}]', '[{"phrase":"produce results"},{"phrase":"produce food"},{"phrase":"produce energy"}]', 'produce (v) sản xuất ≠ produce (n) nông sản', '/prəˈduːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/produce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 9, 'sell', 'bán', 'verb', '[{"en":"They sold their old house and moved to the city.","vi":"Họ đã bán ngôi nhà cũ và chuyển lên thành phố."},{"en":"Do you know if this shop sells phone chargers?","vi":"Bạn có biết cửa hàng này có bán sạc điện thoại không?"},{"en":"Tickets for the concert sold out in two hours.","vi":"Vé buổi hòa nhạc đã bán hết trong hai giờ."}]', '[{"phrase":"sell out"},{"phrase":"sell a house"},{"phrase":"sell tickets"},{"phrase":"sell well"}]', 'sell – sold – sold', '/sel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/sell_/sell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 10, 'short', 'ngắn; thấp', 'adjective', '[{"en":"Let''s take a short break before the next meeting.","vi":"Chúng ta nghỉ giải lao ngắn trước cuộc họp tiếp theo nhé."},{"en":"My sister is short, but she plays basketball very well.","vi":"Chị tôi thấp nhưng chơi bóng rổ rất giỏi."},{"en":"She got her hair cut short for the summer.","vi":"Cô ấy đã cắt tóc ngắn cho mùa hè."}]', '[{"phrase":"short break"},{"phrase":"short hair"},{"phrase":"short time"},{"phrase":"short of"}]', 'người thấp: short (không dùng low)', '/ʃɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/short/short__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 11, 'agree', 'đồng ý; nhất trí', 'verb', '[{"en":"I agree with you about the new schedule.","vi":"Tôi đồng ý với bạn về lịch trình mới."},{"en":"My parents finally agreed to let me travel alone.","vi":"Cuối cùng bố mẹ cũng đồng ý cho tôi đi du lịch một mình."},{"en":"We couldn''t agree on a name for the baby.","vi":"Chúng tôi không thể thống nhất được tên cho em bé."}]', '[{"phrase":"agree with"},{"phrase":"agree to"},{"phrase":"agree on"},{"phrase":"completely agree"}]', 'agree with (người/ý kiến) · agree to (đề nghị) · agree on (vấn đề)', '/əˈɡriː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agree/agree__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 12, 'law', 'luật; pháp luật', 'noun', '[{"en":"In many countries, wearing a seat belt is the law.","vi":"Ở nhiều nước, thắt dây an toàn là quy định của pháp luật."},{"en":"Everyone has to obey the law, even the police.","vi":"Ai cũng phải tuân thủ pháp luật, kể cả cảnh sát."},{"en":"My cousin is studying law at university.","vi":"Anh họ tôi đang học ngành luật ở trường đại học."}]', '[{"phrase":"break the law"},{"phrase":"obey the law"},{"phrase":"against the law"},{"phrase":"study law"}]', NULL, '/lɔː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/law/law__/law__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 13, 'everything', 'mọi thứ; tất cả', 'pronoun', '[{"en":"Thank you for everything you''ve done for me.","vi":"Cảm ơn bạn vì tất cả những gì bạn đã làm cho tôi."},{"en":"Is everything ready for the party tonight?","vi":"Mọi thứ cho bữa tiệc tối nay đã sẵn sàng chưa?"},{"en":"Don''t worry so much, everything will be fine.","vi":"Đừng lo lắng quá, mọi chuyện sẽ ổn thôi."}]', '[{"phrase":"everything else"},{"phrase":"everything is fine"},{"phrase":"thanks for everything"}]', 'everything + động từ số ít', '/ˈevriθɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everything__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 14, 'research', 'nghiên cứu; sự tìm hiểu', 'noun', '[{"en":"She is doing research on children''s sleep habits.","vi":"Cô ấy đang nghiên cứu về thói quen ngủ của trẻ em."},{"en":"Recent research shows that walking is good for the brain.","vi":"Nghiên cứu gần đây cho thấy đi bộ tốt cho não."},{"en":"Do some research before you buy a used car.","vi":"Hãy tìm hiểu trước khi mua một chiếc ô tô cũ."}]', '[{"phrase":"do research"},{"phrase":"research shows"},{"phrase":"carry out research"},{"phrase":"research on"}]', 'không đếm được: some research (không nói a research)', '/ˈriːsɜːrtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/research__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 15, 'cover', 'che, phủ; bao gồm; chi trả', 'verb', '[{"en":"Cover the bowl and put it in the fridge.","vi":"Đậy cái bát lại và cho vào tủ lạnh."},{"en":"Today''s lesson will cover the past simple tense.","vi":"Bài học hôm nay sẽ bao gồm thì quá khứ đơn."},{"en":"Does your insurance cover the cost of the treatment?","vi":"Bảo hiểm của bạn có chi trả chi phí điều trị không?"}]', '[{"phrase":"covered with"},{"phrase":"cover the cost"},{"phrase":"cover a topic"}]', 'be covered with/in: phủ đầy', '/ˈkʌvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cov/cover/cover__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 16, 'paper', 'giấy; tờ báo; giấy tờ', 'noun', '[{"en":"Can I borrow a piece of paper and a pen?","vi":"Cho tôi mượn một tờ giấy và một cây bút được không?"},{"en":"My dad reads the paper every morning with his coffee.","vi":"Bố tôi đọc báo mỗi sáng cùng tách cà phê."},{"en":"Please bring your papers to the office on Monday.","vi":"Vui lòng mang giấy tờ của bạn đến văn phòng vào thứ Hai."}]', '[{"phrase":"a piece of paper"},{"phrase":"sheet of paper"},{"phrase":"read the paper"},{"phrase":"paper bag"}]', 'giấy: không đếm được (a piece of paper); báo, giấy tờ: đếm được', '/ˈpeɪpər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pap/paper/paper__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 17, 'position', 'vị trí; chức vụ; tư thế', 'noun', '[{"en":"Please move the chairs back to their original positions.","vi":"Vui lòng đặt ghế về lại vị trí ban đầu."},{"en":"He applied for a position at a bank.","vi":"Anh ấy đã nộp đơn ứng tuyển một vị trí ở ngân hàng."},{"en":"Try to sleep in a comfortable position.","vi":"Hãy cố gắng ngủ ở tư thế thoải mái."}]', '[{"phrase":"apply for a position"},{"phrase":"comfortable position"},{"phrase":"in position"},{"phrase":"senior position"}]', NULL, '/pəˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/position__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 18, 'near', 'gần', 'preposition', '[{"en":"We live near a park, so the kids play outside a lot.","vi":"Chúng tôi sống gần công viên nên bọn trẻ chơi ngoài trời nhiều."},{"en":"Excuse me, is there a pharmacy near here?","vi":"Xin lỗi, gần đây có hiệu thuốc nào không?"},{"en":"She sat near the window to get more light.","vi":"Cô ấy ngồi gần cửa sổ để có nhiều ánh sáng hơn."}]', '[{"phrase":"near here"},{"phrase":"near the end"},{"phrase":"live near"},{"phrase":"near the window"}]', 'near (không có to) = close to', '/nɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/near_/near__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 19, 'human', '(thuộc) con người; có tính người', 'adjective', '[{"en":"The human body needs water to survive.","vi":"Cơ thể con người cần nước để sống."},{"en":"Don''t be so hard on yourself; it''s only human to make mistakes.","vi":"Đừng khắt khe với bản thân quá; mắc lỗi là chuyện thường tình của con người."},{"en":"Robots still can''t do many jobs that need human skills.","vi":"Robot vẫn chưa làm được nhiều công việc cần đến kỹ năng của con người."}]', '[{"phrase":"human body"},{"phrase":"human being"},{"phrase":"human nature"},{"phrase":"human error"}]', NULL, '/ˈhjuːmən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hum/human/human__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 20, 'computer', 'máy tính', 'noun', '[{"en":"I spend most of my day working on a computer.","vi":"Tôi dành phần lớn thời gian trong ngày làm việc trên máy tính."},{"en":"Turn off the computer before you go to bed.","vi":"Tắt máy tính trước khi đi ngủ nhé."},{"en":"My grandmother is learning to use a computer.","vi":"Bà tôi đang học cách sử dụng máy tính."}]', '[{"phrase":"use a computer"},{"phrase":"computer screen"},{"phrase":"computer game"},{"phrase":"turn off the computer"}]', NULL, '/kəmˈpjuːtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/computer__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 21, 'situation', 'tình huống; tình hình', 'noun', '[{"en":"What would you do in a situation like this?","vi":"Bạn sẽ làm gì trong tình huống như thế này?"},{"en":"The situation at work has improved a lot this year.","vi":"Tình hình ở chỗ làm đã cải thiện nhiều trong năm nay."},{"en":"She stayed calm and handled the difficult situation well.","vi":"Cô ấy giữ bình tĩnh và xử lý tốt tình huống khó khăn."}]', '[{"phrase":"difficult situation"},{"phrase":"handle the situation"},{"phrase":"financial situation"},{"phrase":"in this situation"}]', NULL, '/ˌsɪtʃuˈeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/situa/situation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 22, 'staff', 'nhân viên; đội ngũ nhân viên', 'noun', '[{"en":"The hotel staff were very friendly and helpful.","vi":"Nhân viên khách sạn rất thân thiện và nhiệt tình."},{"en":"Our company has a staff of about fifty people.","vi":"Công ty chúng tôi có đội ngũ khoảng năm mươi nhân viên."},{"en":"All staff must attend the meeting on Friday.","vi":"Tất cả nhân viên phải tham dự cuộc họp vào thứ Sáu."}]', '[{"phrase":"staff member"},{"phrase":"hotel staff"},{"phrase":"staff meeting"},{"phrase":"medical staff"}]', 'danh từ tập hợp; một người: a staff member', '/stæf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/staff/staff__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 23, 'activity', 'hoạt động', 'noun', '[{"en":"Swimming is my favorite activity in the summer.","vi":"Bơi lội là hoạt động tôi thích nhất vào mùa hè."},{"en":"The school offers many activities after class.","vi":"Trường tổ chức nhiều hoạt động sau giờ học."},{"en":"Regular physical activity helps you sleep better.","vi":"Vận động thể chất thường xuyên giúp bạn ngủ ngon hơn."}]', '[{"phrase":"physical activity"},{"phrase":"outdoor activities"},{"phrase":"after-school activities"},{"phrase":"daily activities"}]', NULL, '/ækˈtɪvəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/activ/activity__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 24, 'film', 'phim', 'noun', '[{"en":"Have you seen any good films lately?","vi":"Gần đây bạn có xem bộ phim nào hay không?"},{"en":"We watched an old film on TV last night.","vi":"Tối qua chúng tôi xem một bộ phim cũ trên TV."},{"en":"The film was so funny that we laughed from start to finish.","vi":"Bộ phim buồn cười đến mức chúng tôi cười từ đầu đến cuối."}]', '[{"phrase":"watch a film"},{"phrase":"see a film"},{"phrase":"horror film"},{"phrase":"film star"}]', 'Anh: film · Mỹ: movie', '/fɪlm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/film_/film__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 25, 'morning', 'buổi sáng', 'noun', '[{"en":"I usually go for a run early in the morning.","vi":"Tôi thường chạy bộ vào sáng sớm."},{"en":"The store opens at nine every morning.","vi":"Cửa hàng mở cửa lúc chín giờ mỗi sáng."},{"en":"What are you doing on Saturday morning?","vi":"Bạn làm gì vào sáng thứ Bảy?"}]', '[{"phrase":"in the morning"},{"phrase":"every morning"},{"phrase":"early morning"},{"phrase":"good morning"}]', 'in the morning · on Monday morning', '/ˈmɔːrnɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/morni/morning__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 26, 'war', 'chiến tranh; cuộc chiến', 'noun', '[{"en":"My grandfather rarely talked about his life during the war.","vi":"Ông tôi hiếm khi kể về cuộc sống của ông thời chiến tranh."},{"en":"We are reading a novel about two brothers after the war.","vi":"Chúng tôi đang đọc một cuốn tiểu thuyết về hai anh em sau chiến tranh."},{"en":"Both sides wanted to end the war as soon as possible.","vi":"Cả hai bên đều muốn chấm dứt chiến tranh càng sớm càng tốt."}]', '[{"phrase":"end the war"},{"phrase":"during the war"},{"phrase":"after the war"},{"phrase":"civil war"}]', NULL, '/wɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/war__/war__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 27, 'account', 'tài khoản; bản tường thuật', 'noun', '[{"en":"I opened a bank account when I started my first job.","vi":"Tôi mở tài khoản ngân hàng khi bắt đầu công việc đầu tiên."},{"en":"You need an account to buy tickets on this website.","vi":"Bạn cần có tài khoản để mua vé trên trang web này."},{"en":"She gave the police a clear account of what happened.","vi":"Cô ấy đã kể lại rõ ràng với cảnh sát những gì đã xảy ra."}]', '[{"phrase":"bank account"},{"phrase":"open an account"},{"phrase":"account of"},{"phrase":"take into account"}]', 'take something into account: tính đến điều gì', '/əˈkaʊnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accou/account__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 28, 'shop', 'cửa hàng; tiệm', 'noun', '[{"en":"There''s a small coffee shop on the corner of our street.","vi":"Có một quán cà phê nhỏ ở góc phố nhà chúng tôi."},{"en":"Most shops in town close at eight in the evening.","vi":"Hầu hết cửa hàng trong thị trấn đóng cửa lúc tám giờ tối."},{"en":"I bought this bag at a little shop near the station.","vi":"Tôi mua chiếc túi này ở một tiệm nhỏ gần nhà ga."}]', '[{"phrase":"coffee shop"},{"phrase":"gift shop"},{"phrase":"shop assistant"},{"phrase":"shop window"}]', 'Anh: shop · Mỹ thường dùng: store', '/ʃɑːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shop_/shop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 29, 'major', 'lớn; chủ yếu, quan trọng', 'adjective', '[{"en":"Traffic is a major problem in big cities.","vi":"Giao thông là một vấn đề lớn ở các thành phố lớn."},{"en":"The company made major changes to its website this year.","vi":"Năm nay công ty đã thay đổi lớn trang web của mình."},{"en":"Rice is the major crop in this part of the country.","vi":"Lúa là cây trồng chủ yếu ở vùng này của đất nước."}]', '[{"phrase":"major problem"},{"phrase":"major role"},{"phrase":"major changes"},{"phrase":"major city"}]', NULL, '/ˈmeɪdʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/major__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-12', 30, 'someone', 'ai đó; người nào đó', 'pronoun', '[{"en":"Someone left their umbrella in the classroom.","vi":"Ai đó đã để quên ô trong lớp học."},{"en":"I need someone to help me move this sofa.","vi":"Tôi cần người nào đó giúp tôi chuyển cái ghế sofa này."},{"en":"I think there''s someone at the front door.","vi":"Hình như có ai đó ở cửa trước."}]', '[{"phrase":"someone else"},{"phrase":"talk to someone"},{"phrase":"meet someone"}]', 'someone = somebody', '/ˈsʌmwʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someo/someone__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-13', 'ngsl-1', 'Thông dụng 1–500 · Bộ 13', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 13);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 1, 'above', 'ở trên; trên, hơn', 'preposition', '[{"en":"There is a small shelf above my desk for books.","vi":"Có một kệ sách nhỏ phía trên bàn làm việc của tôi."},{"en":"Her test scores are always above average.","vi":"Điểm kiểm tra của cô ấy luôn trên mức trung bình."},{"en":"We live in the apartment above the bakery.","vi":"Chúng tôi sống trong căn hộ phía trên tiệm bánh."}]', '[{"phrase":"above average"},{"phrase":"above all"},{"phrase":"above sea level"}]', NULL, '/əˈbʌv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abo/above/above__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 2, 'design', 'thiết kế; mẫu thiết kế', 'noun', '[{"en":"I really like the design of your new kitchen.","vi":"Tôi rất thích thiết kế căn bếp mới của bạn."},{"en":"She studied graphic design at college for three years.","vi":"Cô ấy đã học thiết kế đồ họa ở trường đại học trong ba năm."},{"en":"The shirt comes in two different designs.","vi":"Chiếc áo sơ mi này có hai mẫu thiết kế khác nhau."}]', '[{"phrase":"graphic design"},{"phrase":"interior design"},{"phrase":"a simple design"},{"phrase":"new design"}]', NULL, '/dɪˈzaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/design__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 3, 'event', 'sự kiện', 'noun', '[{"en":"The school is holding a special event for parents on Friday.","vi":"Trường sẽ tổ chức một sự kiện đặc biệt dành cho phụ huynh vào thứ Sáu."},{"en":"Getting married is one of the biggest events in life.","vi":"Kết hôn là một trong những sự kiện lớn nhất trong đời."},{"en":"We bought tickets for the event months in advance.","vi":"Chúng tôi đã mua vé cho sự kiện từ nhiều tháng trước."}]', '[{"phrase":"hold an event"},{"phrase":"a special event"},{"phrase":"sporting event"},{"phrase":"major event"}]', NULL, '/ɪˈvent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/event__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 4, 'special', 'đặc biệt; riêng', 'adjective', '[{"en":"We only use these plates on special occasions.","vi":"Chúng tôi chỉ dùng những chiếc đĩa này vào những dịp đặc biệt."},{"en":"The restaurant has a special menu for children.","vi":"Nhà hàng có thực đơn riêng cho trẻ em."},{"en":"You don''t need any special tools to fix this.","vi":"Bạn không cần dụng cụ đặc biệt nào để sửa cái này."}]', '[{"phrase":"special occasion"},{"phrase":"special offer"},{"phrase":"something special"},{"phrase":"special attention"}]', NULL, '/ˈspeʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/special__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 5, 'sometimes', 'đôi khi; thỉnh thoảng', 'adverb', '[{"en":"I sometimes walk to work when the weather is nice.","vi":"Thỉnh thoảng tôi đi bộ đi làm khi trời đẹp."},{"en":"Sometimes it''s better to say nothing at all.","vi":"Đôi khi tốt hơn hết là không nói gì cả."},{"en":"My little brother sometimes even forgets his own birthday.","vi":"Em trai tôi đôi khi còn quên cả sinh nhật của chính mình."}]', '[{"phrase":"sometimes even"},{"phrase":"only sometimes"}]', NULL, '/ˈsʌmtaɪmz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somet/sometimes__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 6, 'condition', 'tình trạng; điều kiện', 'noun', '[{"en":"The old car is still in good condition.","vi":"Chiếc xe cũ vẫn còn trong tình trạng tốt."},{"en":"Many workers complained about their poor working conditions.","vi":"Nhiều công nhân phàn nàn về điều kiện làm việc tồi tệ của họ."},{"en":"You can borrow my laptop on one condition: be careful with it.","vi":"Bạn có thể mượn máy tính xách tay của tôi với một điều kiện: hãy cẩn thận với nó."}]', '[{"phrase":"in good condition"},{"phrase":"working conditions"},{"phrase":"weather conditions"},{"phrase":"on one condition"}]', NULL, '/kənˈdɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xcondition__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 7, 'carry', 'mang, xách; chở', 'verb', '[{"en":"Can you help me carry these bags upstairs?","vi":"Bạn có thể giúp tôi xách mấy cái túi này lên lầu không?"},{"en":"Do you always carry an umbrella in your bag?","vi":"Bạn có luôn mang theo ô trong túi không?"},{"en":"The bus can carry up to fifty passengers.","vi":"Chiếc xe buýt có thể chở tối đa năm mươi hành khách."}]', '[{"phrase":"carry a bag"},{"phrase":"carry an umbrella"},{"phrase":"carry passengers"}]', NULL, '/ˈkæri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carry/carry__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 8, 'choose', 'chọn; quyết định', 'verb', '[{"en":"It took me an hour to choose a birthday gift.","vi":"Tôi mất một tiếng để chọn một món quà sinh nhật."},{"en":"You can choose between tea and coffee.","vi":"Bạn có thể chọn giữa trà và cà phê."},{"en":"She chose to stay home instead of going out.","vi":"Cô ấy quyết định ở nhà thay vì ra ngoài."}]', '[{"phrase":"choose between"},{"phrase":"choose carefully"},{"phrase":"free to choose"}]', 'choose – chose – chosen', '/tʃuːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choos/choose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 9, 'father', 'bố, cha', 'noun', '[{"en":"My father taught me how to ride a bike.","vi":"Bố tôi đã dạy tôi cách đi xe đạp."},{"en":"He''s excited to become a father next spring.","vi":"Anh ấy rất háo hức vì sắp được làm bố vào mùa xuân tới."},{"en":"Her father works as a nurse at the city hospital.","vi":"Bố cô ấy làm y tá ở bệnh viện thành phố."}]', '[{"phrase":"become a father"},{"phrase":"father and son"},{"phrase":"a proud father"}]', NULL, '/ˈfɑːðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fat/fathe/father__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 10, 'decision', 'quyết định', 'noun', '[{"en":"Moving to a new city was a difficult decision.","vi":"Chuyển đến một thành phố mới là một quyết định khó khăn."},{"en":"We need to make a decision by Friday.","vi":"Chúng ta cần đưa ra quyết định trước thứ Sáu."},{"en":"I think you made the right decision.","vi":"Tôi nghĩ bạn đã đưa ra quyết định đúng đắn."}]', '[{"phrase":"make a decision"},{"phrase":"the right decision"},{"phrase":"a difficult decision"},{"phrase":"final decision"}]', NULL, '/dɪˈsɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decis/decision__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 11, 'table', 'cái bàn; bảng (số liệu)', 'noun', '[{"en":"Please put the plates on the kitchen table.","vi":"Hãy đặt những cái đĩa lên bàn bếp."},{"en":"I booked a table for four at seven o''clock.","vi":"Tôi đã đặt một bàn cho bốn người lúc bảy giờ."},{"en":"The table below shows the prices for each room.","vi":"Bảng dưới đây cho thấy giá của từng phòng."}]', '[{"phrase":"kitchen table"},{"phrase":"book a table"},{"phrase":"set the table"},{"phrase":"at the table"}]', NULL, '/ˈteɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tab/table/table__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 12, 'certain', 'chắc chắn; nhất định', 'adjective', '[{"en":"Are you certain that you locked the front door?","vi":"Bạn có chắc là mình đã khóa cửa trước không?"},{"en":"The store is only open on certain days of the week.","vi":"Cửa hàng chỉ mở cửa vào một số ngày nhất định trong tuần."},{"en":"It takes a certain amount of time to learn a new language.","vi":"Cần một khoảng thời gian nhất định để học một ngôn ngữ mới."}]', '[{"phrase":"a certain amount"},{"phrase":"for certain"},{"phrase":"almost certain"}]', NULL, '/ˈsɜːrtn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/certa/certain__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 13, 'forward', 'về phía trước; tới trước', 'adverb', '[{"en":"She leaned forward to hear what he was saying.","vi":"Cô ấy nghiêng người về phía trước để nghe anh ấy đang nói gì."},{"en":"Please take one step forward when I call your name.","vi":"Khi tôi gọi tên, hãy bước lên phía trước một bước."},{"en":"The line moved forward slowly as the doors opened.","vi":"Hàng người chậm rãi tiến lên phía trước khi cửa mở ra."}]', '[{"phrase":"step forward"},{"phrase":"move forward"},{"phrase":"lean forward"},{"phrase":"look forward to"}]', 'look forward to + V-ing: mong chờ', '/ˈfɔːrwərd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forwa/forward__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 14, 'main', 'chính; chủ yếu', 'adjective', '[{"en":"The main entrance is on the other side of the building.","vi":"Lối vào chính ở phía bên kia tòa nhà."},{"en":"What is the main reason you want this job?","vi":"Lý do chính khiến bạn muốn công việc này là gì?"},{"en":"Chicken is the main ingredient in this soup.","vi":"Thịt gà là nguyên liệu chính của món súp này."}]', '[{"phrase":"main reason"},{"phrase":"main road"},{"phrase":"main entrance"},{"phrase":"main course"}]', NULL, '/meɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/main_/main__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 15, 'die', 'chết, qua đời; hết pin, tắt', 'verb', '[{"en":"My grandfather died when I was ten years old.","vi":"Ông tôi qua đời khi tôi mười tuổi."},{"en":"All the plants died because nobody watered them.","vi":"Tất cả cây cối đều chết vì không ai tưới nước."},{"en":"My laptop battery died in the middle of the meeting.","vi":"Máy tính xách tay của tôi hết pin giữa buổi họp."}]', '[{"phrase":"die of"},{"phrase":"die young"},{"phrase":"the battery died"}]', 'die – died – died; V-ing: dying', '/daɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/die/die__/die__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 16, 'bear', 'chịu đựng; chịu (chi phí, trách nhiệm)', 'verb', '[{"en":"I can''t bear the noise from the building site next door.","vi":"Tôi không chịu nổi tiếng ồn từ công trường bên cạnh."},{"en":"She couldn''t bear to see her children so unhappy.","vi":"Cô ấy không chịu nổi khi thấy các con mình buồn như vậy."},{"en":"The company will bear the cost of your training.","vi":"Công ty sẽ chịu chi phí đào tạo cho bạn."}]', '[{"phrase":"can''t bear"},{"phrase":"bear the cost"},{"phrase":"bear in mind"}]', 'bear – bore – borne; danh từ: con gấu', '/ber/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/bear_/bear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 17, 'cut', 'cắt; cắt giảm', 'verb', '[{"en":"Can you cut the cake into eight pieces?","vi":"Bạn có thể cắt bánh thành tám miếng không?"},{"en":"I cut my finger while I was cooking dinner.","vi":"Tôi bị đứt tay khi đang nấu bữa tối."},{"en":"The company plans to cut costs next year.","vi":"Công ty dự định cắt giảm chi phí vào năm tới."}]', '[{"phrase":"cut costs"},{"phrase":"cut in half"},{"phrase":"cut into pieces"}]', 'cut – cut – cut', '/kʌt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cut/cut__/cut__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 18, 'describe', 'mô tả, miêu tả', 'verb', '[{"en":"Can you describe the man you saw last night?","vi":"Bạn có thể mô tả người đàn ông bạn thấy tối qua không?"},{"en":"She described her new job as busy but exciting.","vi":"Cô ấy mô tả công việc mới của mình là bận rộn nhưng thú vị."},{"en":"It''s hard to describe how beautiful the view was.","vi":"Thật khó để miêu tả khung cảnh đẹp đến mức nào."}]', '[{"phrase":"describe in detail"},{"phrase":"hard to describe"},{"phrase":"accurately describe"}]', NULL, '/dɪˈskraɪb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/descr/describe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 19, 'available', 'có sẵn; còn trống; rảnh', 'adjective', '[{"en":"Tickets are available online or at the front desk.","vi":"Vé có bán trên mạng hoặc tại quầy lễ tân."},{"en":"Is the manager available to talk right now?","vi":"Quản lý có rảnh để nói chuyện bây giờ không?"},{"en":"Sorry, there are no rooms available this weekend.","vi":"Xin lỗi, cuối tuần này không còn phòng trống."}]', '[{"phrase":"available online"},{"phrase":"widely available"},{"phrase":"freely available"},{"phrase":"readily available"}]', NULL, '/əˈveɪləbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ava/avail/available__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 20, 'especially', 'đặc biệt là, nhất là; dành riêng', 'adverb', '[{"en":"I love fruit, especially mangoes and bananas.","vi":"Tôi thích trái cây, nhất là xoài và chuối."},{"en":"The roads are very busy, especially in the morning.","vi":"Đường xá rất đông đúc, nhất là vào buổi sáng."},{"en":"This cake was made especially for your birthday.","vi":"Chiếc bánh này được làm riêng cho sinh nhật của bạn."}]', '[{"phrase":"especially for"},{"phrase":"especially when"},{"phrase":"especially important"}]', NULL, '/ɪˈspeʃəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/esp/espec/especially__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 21, 'strong', 'mạnh; khỏe; đậm', 'adjective', '[{"en":"He''s strong enough to lift the sofa by himself.","vi":"Anh ấy đủ khỏe để tự mình nâng chiếc ghế sofa."},{"en":"A strong wind blew the leaves off the trees.","vi":"Một cơn gió mạnh thổi lá rụng khỏi cây."},{"en":"I like my coffee strong with no sugar.","vi":"Tôi thích cà phê đậm và không đường."}]', '[{"phrase":"strong wind"},{"phrase":"strong coffee"},{"phrase":"a strong smell"},{"phrase":"strong enough"}]', NULL, '/strɔːŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stron/strong__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 22, 'rise', 'tăng; mọc, bốc lên', 'verb', '[{"en":"In summer, the sun rises before five o''clock.","vi":"Vào mùa hè, mặt trời mọc trước năm giờ sáng."},{"en":"House prices have risen quickly in the past few years.","vi":"Giá nhà đã tăng nhanh trong vài năm qua."},{"en":"We watched the smoke rise slowly into the sky.","vi":"Chúng tôi nhìn làn khói từ từ bốc lên trời."}]', '[{"phrase":"the sun rises"},{"phrase":"prices rise"},{"phrase":"rise sharply"}]', 'rise – rose – risen', '/raɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ris/rise_/rise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 23, 'girl', 'cô gái; bé gái; con gái', 'noun', '[{"en":"There are ten boys and twelve girls in my class.","vi":"Lớp tôi có mười bạn nam và mười hai bạn nữ."},{"en":"Their little girl just started school this year.","vi":"Con gái nhỏ của họ vừa mới bắt đầu đi học năm nay."},{"en":"The girl at the front desk gave us our room keys.","vi":"Cô gái ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."}]', '[{"phrase":"little girl"},{"phrase":"young girl"},{"phrase":"baby girl"},{"phrase":"teenage girl"}]', NULL, '/ɡɜːrl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gir/girl_/girl__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 24, 'maybe', 'có lẽ; có thể', 'adverb', '[{"en":"Maybe we should take a taxi because it''s raining.","vi":"Có lẽ chúng ta nên đi taxi vì trời đang mưa."},{"en":"We could go to the beach, or maybe the park.","vi":"Chúng ta có thể đi biển, hoặc có lẽ đi công viên."},{"en":"She isn''t answering her phone, so maybe she''s asleep.","vi":"Cô ấy không nghe máy, nên có lẽ cô ấy đang ngủ."}]', '[{"phrase":"or maybe"},{"phrase":"maybe not"},{"phrase":"maybe later"}]', NULL, '/ˈmeɪbi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/may/maybe/maybe__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 25, 'community', 'cộng đồng', 'noun', '[{"en":"Our community is raising money to build a new playground.","vi":"Cộng đồng chúng tôi đang quyên tiền để xây một sân chơi mới."},{"en":"She volunteers at the community center every Saturday.","vi":"Cô ấy làm tình nguyện ở trung tâm cộng đồng vào mỗi thứ Bảy."},{"en":"People in a small community usually know each other well.","vi":"Người dân trong một cộng đồng nhỏ thường biết rõ về nhau."}]', '[{"phrase":"local community"},{"phrase":"community center"},{"phrase":"small community"},{"phrase":"community service"}]', NULL, '/kəˈmjuːnəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/community__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 26, 'else', 'khác; nữa', 'adverb', '[{"en":"Would you like anything else to drink?","vi":"Bạn có muốn uống gì nữa không?"},{"en":"Everyone else went home, but I stayed late.","vi":"Mọi người khác đều về nhà, nhưng tôi ở lại muộn."},{"en":"If this shop is closed, let''s try somewhere else.","vi":"Nếu cửa hàng này đóng cửa thì chúng ta thử chỗ khác nhé."}]', '[{"phrase":"anything else"},{"phrase":"someone else"},{"phrase":"somewhere else"},{"phrase":"or else"}]', NULL, '/els/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/els/else_/else__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 27, 'particular', 'cụ thể, riêng; đặc biệt', 'adjective', '[{"en":"Is there a particular day that works best for you?","vi":"Có ngày cụ thể nào thuận tiện nhất cho bạn không?"},{"en":"I don''t like this particular brand of coffee.","vi":"Riêng nhãn hiệu cà phê này thì tôi không thích."},{"en":"Nothing in particular happened at work today.","vi":"Hôm nay ở chỗ làm không có gì đặc biệt xảy ra."}]', '[{"phrase":"in particular"},{"phrase":"for no particular reason"},{"phrase":"pay particular attention"}]', NULL, '/pərˈtɪkjələr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/particular__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 28, 'role', 'vai trò; vai diễn', 'noun', '[{"en":"Parents play an important role in their children''s education.","vi":"Cha mẹ đóng vai trò quan trọng trong việc học của con cái."},{"en":"She got the main role in the school play.","vi":"Cô ấy được đóng vai chính trong vở kịch của trường."},{"en":"What is your role in the new project?","vi":"Vai trò của bạn trong dự án mới là gì?"}]', '[{"phrase":"play a role"},{"phrase":"an important role"},{"phrase":"key role"},{"phrase":"leading role"}]', NULL, '/rəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/role_/role__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 29, 'join', 'tham gia, gia nhập; cùng (ai)', 'verb', '[{"en":"My sister joined a tennis club last month.","vi":"Chị tôi đã tham gia một câu lạc bộ quần vợt vào tháng trước."},{"en":"Would you like to join us for dinner tonight?","vi":"Tối nay bạn có muốn ăn tối cùng chúng tôi không?"},{"en":"He joined the company right after he finished college.","vi":"Anh ấy vào làm ở công ty ngay sau khi học xong đại học."}]', '[{"phrase":"join a club"},{"phrase":"join us"},{"phrase":"join the team"},{"phrase":"join in"}]', NULL, '/dʒɔɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joi/join_/join__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-13', 30, 'difficult', 'khó; khó khăn', 'adjective', '[{"en":"The math test was more difficult than I expected.","vi":"Bài kiểm tra toán khó hơn tôi nghĩ."},{"en":"It''s difficult to find a cheap apartment in this city.","vi":"Rất khó tìm được một căn hộ giá rẻ ở thành phố này."},{"en":"Last year was a difficult time for our family.","vi":"Năm ngoái là khoảng thời gian khó khăn đối với gia đình tôi."}]', '[{"phrase":"difficult time"},{"phrase":"difficult decision"},{"phrase":"difficult question"},{"phrase":"find it difficult"}]', NULL, '/ˈdɪfɪkəlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffi/difficult__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-1-14', 'ngsl-1', 'Thông dụng 1–500 · Bộ 14', 'New General Service List, thứ hạng 1–500', '#3da9fc', 'BookOpen', 14);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 1, 'please', 'làm ơn; vui lòng', 'exclamation', '[{"en":"Could you please turn the music down a little?","vi":"Bạn làm ơn vặn nhỏ nhạc một chút được không?"},{"en":"Please take off your shoes before you come inside.","vi":"Vui lòng cởi giày trước khi vào trong."},{"en":"Two coffees and a glass of water, please.","vi":"Làm ơn cho tôi hai cà phê và một ly nước."}]', '[{"phrase":"yes, please"},{"phrase":"please sit down"},{"phrase":"please note"}]', NULL, '/pliːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/please__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 2, 'detail', 'chi tiết', 'noun', '[{"en":"Can you send me more details about the job?","vi":"Bạn có thể gửi cho tôi thêm thông tin chi tiết về công việc không?"},{"en":"She remembers every detail of her wedding day.","vi":"Cô ấy nhớ từng chi tiết của ngày cưới."},{"en":"We will explain the plan in detail at the meeting.","vi":"Chúng tôi sẽ giải thích kế hoạch một cách chi tiết trong buổi họp."}]', '[{"phrase":"in detail"},{"phrase":"more details"},{"phrase":"contact details"},{"phrase":"attention to detail"}]', NULL, '/ˈdiːteɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detai/detail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 3, 'difference', 'sự khác biệt; sự chênh lệch', 'noun', '[{"en":"Can you tell the difference between these two colors?","vi":"Bạn có nhận ra sự khác biệt giữa hai màu này không?"},{"en":"There is a big difference between living in a city and a village.","vi":"Có sự khác biệt lớn giữa việc sống ở thành phố và ở làng quê."},{"en":"The price difference between the two phones is about fifty dollars.","vi":"Chênh lệch giá giữa hai chiếc điện thoại là khoảng năm mươi đô la."}]', '[{"phrase":"tell the difference"},{"phrase":"make a difference"},{"phrase":"big difference"},{"phrase":"difference between"}]', NULL, '/ˈdɪfrəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/difference__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 4, 'action', 'hành động', 'noun', '[{"en":"We need to take action before the problem gets worse.","vi":"Chúng ta cần hành động trước khi vấn đề trở nên tồi tệ hơn."},{"en":"Her quick action saved the little boy''s life.","vi":"Hành động nhanh chóng của cô ấy đã cứu sống cậu bé."},{"en":"My brother loves watching action movies on weekends.","vi":"Anh trai tôi thích xem phim hành động vào cuối tuần."}]', '[{"phrase":"take action"},{"phrase":"quick action"},{"phrase":"action movie"}]', NULL, '/ˈækʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actio/action__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 5, 'health', 'sức khỏe', 'noun', '[{"en":"Smoking is very bad for your health.","vi":"Hút thuốc rất có hại cho sức khỏe của bạn."},{"en":"My grandmother is in good health for her age.","vi":"So với tuổi của mình, bà tôi vẫn có sức khỏe tốt."},{"en":"Regular exercise improves both your physical and mental health.","vi":"Tập thể dục đều đặn cải thiện cả sức khỏe thể chất lẫn tinh thần."}]', '[{"phrase":"good health"},{"phrase":"mental health"},{"phrase":"health care"},{"phrase":"bad for your health"}]', 'không đếm được', '/helθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/healt/health__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 6, 'eat', 'ăn', 'verb', '[{"en":"We usually eat dinner together at seven o''clock.","vi":"Chúng tôi thường ăn tối cùng nhau lúc bảy giờ."},{"en":"Have you eaten anything since breakfast this morning?","vi":"Bạn đã ăn gì từ bữa sáng nay chưa?"},{"en":"She ate too much cake and felt sick afterward.","vi":"Cô ấy ăn quá nhiều bánh và sau đó thấy khó chịu."}]', '[{"phrase":"eat dinner"},{"phrase":"eat breakfast"},{"phrase":"eat out"},{"phrase":"eat well"}]', 'eat – ate – eaten', '/iːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eat/eat__/eat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 7, 'step', 'bước; bậc thềm', 'noun', '[{"en":"Watch your step because the floor is wet.","vi":"Cẩn thận bước chân vì sàn nhà bị ướt."},{"en":"The first step is to fill out this form.","vi":"Bước đầu tiên là điền vào mẫu đơn này."},{"en":"The children sat on the front steps eating ice cream.","vi":"Bọn trẻ ngồi ăn kem trên bậc thềm trước nhà."}]', '[{"phrase":"first step"},{"phrase":"next step"},{"phrase":"step by step"},{"phrase":"take a step"}]', NULL, '/step/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/step_/step__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 8, 'true', 'đúng, thật; có thật; thật sự', 'adjective', '[{"en":"Is it true that you''re moving to Canada next year?","vi":"Có thật là năm sau bạn sẽ chuyển đến Canada không?"},{"en":"The movie is based on a true story.","vi":"Bộ phim dựa trên một câu chuyện có thật."},{"en":"A true friend will help you when things are hard.","vi":"Một người bạn thật sự sẽ giúp bạn khi gặp khó khăn."}]', '[{"phrase":"true story"},{"phrase":"come true"},{"phrase":"true friend"}]', NULL, '/truː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/true_/true__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 9, 'phone', 'điện thoại', 'noun', '[{"en":"Can I borrow your phone for a minute?","vi":"Cho tôi mượn điện thoại của bạn một phút được không?"},{"en":"My mom called me, but my phone was off.","vi":"Mẹ gọi cho tôi nhưng điện thoại của tôi đang tắt."},{"en":"She was on the phone with her sister for an hour.","vi":"Cô ấy nói chuyện điện thoại với chị gái suốt một tiếng."}]', '[{"phrase":"phone number"},{"phrase":"phone call"},{"phrase":"on the phone"},{"phrase":"answer the phone"}]', NULL, '/fəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/phone/phone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 10, 'draw', 'vẽ; kéo; thu hút', 'verb', '[{"en":"My little sister loves to draw animals.","vi":"Em gái tôi rất thích vẽ động vật."},{"en":"She drew the curtains to keep the sunlight out.","vi":"Cô ấy kéo rèm lại để chắn ánh nắng."},{"en":"The street festival drew a large crowd this year.","vi":"Lễ hội đường phố năm nay đã thu hút rất đông người."}]', '[{"phrase":"draw a picture"},{"phrase":"draw the curtains"},{"phrase":"draw attention"},{"phrase":"draw a crowd"}]', 'draw – drew – drawn', '/drɔː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draw_/draw__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 11, 'white', 'trắng; màu trắng', 'adjective', '[{"en":"She wore a white dress to the party.","vi":"Cô ấy mặc một chiếc váy trắng đến bữa tiệc."},{"en":"His hair turned white when he was only fifty.","vi":"Tóc ông ấy bạc trắng khi mới năm mươi tuổi."},{"en":"The walls in my bedroom are painted white.","vi":"Tường phòng ngủ của tôi được sơn màu trắng."}]', '[{"phrase":"white shirt"},{"phrase":"white wine"},{"phrase":"black and white"},{"phrase":"turn white"}]', NULL, '/waɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/white/white__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 12, 'date', 'ngày tháng; cuộc hẹn hò', 'noun', '[{"en":"Please write today''s date at the top of the page.","vi":"Vui lòng ghi ngày hôm nay ở đầu trang."},{"en":"Have you set a date for the wedding yet?","vi":"Bạn đã chọn ngày tổ chức đám cưới chưa?"},{"en":"He asked her out on a date last Friday.","vi":"Thứ Sáu tuần trước anh ấy đã mời cô ấy đi hẹn hò."}]', '[{"phrase":"date of birth"},{"phrase":"set a date"},{"phrase":"go on a date"}]', NULL, '/deɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/date_/date__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 13, 'practice', 'sự luyện tập; thực tế', 'noun', '[{"en":"Learning a new language takes a lot of practice.","vi":"Học một ngôn ngữ mới cần luyện tập rất nhiều."},{"en":"The team has soccer practice every Tuesday afternoon.","vi":"Đội có buổi tập bóng đá vào mỗi chiều thứ Ba."},{"en":"The idea sounds good, but it may not work in practice.","vi":"Ý tưởng nghe có vẻ hay nhưng trên thực tế có thể không hiệu quả."}]', '[{"phrase":"a lot of practice"},{"phrase":"in practice"},{"phrase":"put into practice"}]', 'Anh: practise (động từ) · Mỹ: practice', '/ˈpræktɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practice__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 14, 'model', 'mẫu, kiểu; người mẫu; mô hình', 'noun', '[{"en":"This phone is an older model, but it still works well.","vi":"Chiếc điện thoại này là mẫu cũ nhưng vẫn dùng tốt."},{"en":"She worked as a fashion model before becoming a teacher.","vi":"Cô ấy từng làm người mẫu thời trang trước khi trở thành giáo viên."},{"en":"My son spent all weekend building a model plane.","vi":"Con trai tôi dành cả cuối tuần để lắp ráp một chiếc máy bay mô hình."}]', '[{"phrase":"latest model"},{"phrase":"fashion model"},{"phrase":"role model"}]', NULL, '/ˈmɑːdl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/model/model__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 15, 'raise', 'giơ lên, nâng lên; tăng; nuôi nấng', 'verb', '[{"en":"Raise your hand if you have a question.","vi":"Hãy giơ tay nếu bạn có câu hỏi."},{"en":"The company plans to raise prices next month.","vi":"Công ty dự định tăng giá vào tháng tới."},{"en":"She raised three children on her own.","vi":"Cô ấy một mình nuôi ba đứa con."}]', '[{"phrase":"raise your hand"},{"phrase":"raise prices"},{"phrase":"raise money"},{"phrase":"raise children"}]', 'raise + tân ngữ ≠ rise (không có tân ngữ)', '/reɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/raise/raise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 16, 'customer', 'khách hàng', 'noun', '[{"en":"The store offers free delivery to its regular customers.","vi":"Cửa hàng giao hàng miễn phí cho khách hàng quen."},{"en":"She stayed polite even when the customer started shouting.","vi":"Cô ấy vẫn lịch sự ngay cả khi vị khách bắt đầu la hét."},{"en":"Please call customer service if the product arrives damaged.","vi":"Vui lòng gọi bộ phận chăm sóc khách hàng nếu sản phẩm bị hư hỏng khi đến nơi."}]', '[{"phrase":"customer service"},{"phrase":"regular customer"},{"phrase":"new customers"}]', NULL, '/ˈkʌstəmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cus/custo/customer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 17, 'front', 'phía trước; mặt trước', 'noun', '[{"en":"Let''s sit at the front so we can see better.","vi":"Chúng ta ngồi ở phía trước để nhìn rõ hơn nhé."},{"en":"There is a small garden in front of our house.","vi":"Có một khu vườn nhỏ ở phía trước nhà chúng tôi."},{"en":"Write your name on the front of the envelope.","vi":"Hãy viết tên bạn ở mặt trước phong bì."}]', '[{"phrase":"in front of"},{"phrase":"at the front"},{"phrase":"front door"},{"phrase":"front seat"}]', NULL, '/frʌnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fro/front/front__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 18, 'explain', 'giải thích', 'verb', '[{"en":"Can you explain how this machine works?","vi":"Bạn có thể giải thích cái máy này hoạt động thế nào không?"},{"en":"The teacher explained the rules of the game again.","vi":"Giáo viên giải thích lại luật chơi một lần nữa."},{"en":"He never explained why he left the party so early.","vi":"Anh ấy chưa bao giờ giải thích tại sao anh ấy rời bữa tiệc sớm như vậy."}]', '[{"phrase":"explain why"},{"phrase":"explain how"},{"phrase":"clearly explain"},{"phrase":"explain the reason"}]', 'explain something to someone (không nói: explain someone something)', '/ɪkˈspleɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expla/explain__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 19, 'door', 'cửa ra vào', 'noun', '[{"en":"Please close the door when you leave.","vi":"Vui lòng đóng cửa khi bạn ra về."},{"en":"I think someone is knocking at the front door.","vi":"Hình như có ai đang gõ cửa trước."},{"en":"Our new neighbors live right next door.","vi":"Hàng xóm mới của chúng tôi sống ngay nhà bên cạnh."}]', '[{"phrase":"open the door"},{"phrase":"close the door"},{"phrase":"front door"},{"phrase":"next door"}]', NULL, '/dɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doo/door_/door__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 20, 'outside', 'bên ngoài; ra ngoài', 'adverb', '[{"en":"The kids are playing outside in the garden.","vi":"Bọn trẻ đang chơi bên ngoài vườn."},{"en":"It''s too cold to go outside today.","vi":"Hôm nay trời quá lạnh để ra ngoài."},{"en":"Please wait outside until the doctor calls your name.","vi":"Vui lòng đợi bên ngoài cho đến khi bác sĩ gọi tên bạn."}]', '[{"phrase":"go outside"},{"phrase":"wait outside"},{"phrase":"play outside"}]', NULL, '/ˌaʊtˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outsi/outside__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 21, 'behind', 'phía sau, đằng sau; tụt lại phía sau', 'preposition', '[{"en":"The cat is hiding behind the sofa.","vi":"Con mèo đang trốn sau ghế sofa."},{"en":"There is a small park behind the school.","vi":"Có một công viên nhỏ phía sau trường học."},{"en":"She was sick for a week and fell behind in class.","vi":"Cô ấy bị ốm một tuần nên bị tụt lại so với cả lớp."}]', '[{"phrase":"behind the house"},{"phrase":"right behind"},{"phrase":"fall behind"},{"phrase":"leave behind"}]', NULL, '/bɪˈhaɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behin/behind__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 22, 'economic', 'kinh tế', 'adjective', '[{"en":"The country has seen strong economic growth this year.","vi":"Đất nước đã đạt mức tăng trưởng kinh tế mạnh mẽ trong năm nay."},{"en":"Many families are struggling because of the economic crisis.","vi":"Nhiều gia đình đang gặp khó khăn vì khủng hoảng kinh tế."},{"en":"The new factory will bring economic benefits to the town.","vi":"Nhà máy mới sẽ mang lại lợi ích kinh tế cho thị trấn."}]', '[{"phrase":"economic growth"},{"phrase":"economic crisis"},{"phrase":"economic development"},{"phrase":"economic policy"}]', 'economic (kinh tế) ≠ economical (tiết kiệm)', '/ˌiːkəˈnɑːmɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economic__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 23, 'site', 'địa điểm, khu đất; công trường; trang web', 'noun', '[{"en":"They chose a quiet site near the river for the new school.","vi":"Họ đã chọn một khu đất yên tĩnh gần sông để xây trường mới."},{"en":"Workers must wear helmets at the construction site.","vi":"Công nhân phải đội mũ bảo hộ tại công trường."},{"en":"You can find more information on the company''s site.","vi":"Bạn có thể tìm thêm thông tin trên trang web của công ty."}]', '[{"phrase":"construction site"},{"phrase":"on site"},{"phrase":"historic site"}]', NULL, '/saɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/site_/site__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 24, 'approach', 'cách tiếp cận, phương pháp; sự đến gần', 'noun', '[{"en":"Her teacher has a very creative approach to teaching math.","vi":"Giáo viên của cô ấy có cách tiếp cận rất sáng tạo trong việc dạy toán."},{"en":"If this plan doesn''t work, we''ll try a different approach.","vi":"Nếu kế hoạch này không hiệu quả, chúng ta sẽ thử một cách tiếp cận khác."},{"en":"With the approach of winter, the days are getting shorter.","vi":"Khi mùa đông đến gần, ngày ngắn dần đi."}]', '[{"phrase":"different approach"},{"phrase":"new approach"},{"phrase":"approach to"},{"phrase":"take an approach"}]', 'Động từ: approach (tiến lại gần)', '/əˈprəʊtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 25, 'teacher', 'giáo viên', 'noun', '[{"en":"My English teacher gives us homework every day.","vi":"Giáo viên tiếng Anh của tôi giao bài tập về nhà mỗi ngày."},{"en":"She wants to become a teacher after she finishes college.","vi":"Cô ấy muốn trở thành giáo viên sau khi học xong đại học."},{"en":"Ask your teacher if you don''t understand the lesson.","vi":"Hãy hỏi giáo viên nếu bạn không hiểu bài."}]', '[{"phrase":"English teacher"},{"phrase":"math teacher"},{"phrase":"good teacher"},{"phrase":"become a teacher"}]', NULL, '/ˈtiːtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/teach/teacher__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 26, 'land', 'đất, đất đai; đất liền', 'noun', '[{"en":"My grandparents own some land in the countryside.","vi":"Ông bà tôi có một mảnh đất ở quê."},{"en":"The land here is good for growing rice.","vi":"Đất ở đây rất tốt để trồng lúa."},{"en":"After two weeks at sea, the sailors were happy to see land.","vi":"Sau hai tuần trên biển, các thủy thủ vui mừng khi nhìn thấy đất liền."}]', '[{"phrase":"piece of land"},{"phrase":"on land"},{"phrase":"buy land"}]', 'không đếm được · Động từ: land (hạ cánh)', '/lænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/land_/land__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 27, 'charge', 'phí; sự phụ trách', 'noun', '[{"en":"There is no charge for children under five.","vi":"Trẻ em dưới năm tuổi được miễn phí."},{"en":"Who is in charge of this project while the manager is away?","vi":"Ai phụ trách dự án này khi quản lý đi vắng?"},{"en":"The hotel adds a small charge for late checkout.","vi":"Khách sạn tính thêm một khoản phí nhỏ nếu trả phòng muộn."}]', '[{"phrase":"in charge of"},{"phrase":"free of charge"},{"phrase":"extra charge"},{"phrase":"service charge"}]', 'Động từ: charge (tính phí; sạc pin)', '/tʃɑːrdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/charg/charge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 28, 'finally', 'cuối cùng; sau cùng', 'adverb', '[{"en":"After three hours of waiting, the bus finally arrived.","vi":"Sau ba tiếng chờ đợi, cuối cùng xe buýt cũng đến."},{"en":"I finally finished reading that long book last night.","vi":"Tối qua cuối cùng tôi cũng đọc xong cuốn sách dài đó."},{"en":"Finally, add some salt and serve the soup hot.","vi":"Sau cùng, thêm chút muối và dùng súp khi còn nóng."}]', '[{"phrase":"finally arrive"},{"phrase":"finally decide"},{"phrase":"finally realize"}]', NULL, '/ˈfaɪnəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/finally__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-1-14', 29, 'sign', 'biển báo; dấu hiệu', 'noun', '[{"en":"Follow the signs to the train station.","vi":"Hãy đi theo các biển chỉ dẫn đến ga tàu."},{"en":"A high fever can be a sign of a serious illness.","vi":"Sốt cao có thể là dấu hiệu của một căn bệnh nghiêm trọng."},{"en":"Dark clouds are often a sign that rain is coming.","vi":"Mây đen thường là dấu hiệu sắp có mưa."}]', '[{"phrase":"road sign"},{"phrase":"warning sign"},{"phrase":"a sign of"},{"phrase":"follow the signs"}]', 'Động từ: sign (ký tên)', '/saɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sign_/sign__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-01', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 1', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 1, 'claim', 'khẳng định, cho rằng; đòi, yêu cầu', 'verb', '[{"en":"He claims that he saw a ghost in the old house.","vi":"Anh ấy khẳng định đã nhìn thấy ma trong ngôi nhà cũ."},{"en":"The company claims its new phone battery lasts two days.","vi":"Công ty cho rằng pin điện thoại mới của họ dùng được hai ngày."},{"en":"You can claim the cost of the taxi back from your company.","vi":"Bạn có thể đòi công ty hoàn lại tiền taxi."}]', '[{"phrase":"claim that"},{"phrase":"claim to be"},{"phrase":"claim compensation"},{"phrase":"claim back"}]', NULL, '/kleɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claim/claim__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 2, 'relationship', 'mối quan hệ; mối tình', 'noun', '[{"en":"She has a very close relationship with her grandmother.","vi":"Cô ấy có mối quan hệ rất gắn bó với bà của mình."},{"en":"Good communication is important in any relationship.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ mối quan hệ nào."},{"en":"Are you in a relationship, or are you still single?","vi":"Bạn đang có người yêu hay vẫn còn độc thân?"}]', '[{"phrase":"close relationship"},{"phrase":"relationship with"},{"phrase":"in a relationship"},{"phrase":"build a relationship"}]', NULL, '/rɪˈleɪʃnʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relationship__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 3, 'travel', 'đi du lịch; đi lại, di chuyển', 'verb', '[{"en":"We love to travel abroad during the summer holidays.","vi":"Chúng tôi thích đi du lịch nước ngoài vào kỳ nghỉ hè."},{"en":"My father travels a lot for work.","vi":"Bố tôi đi công tác rất nhiều."},{"en":"It takes an hour to travel from my house to the city center.","vi":"Đi từ nhà tôi đến trung tâm thành phố mất một tiếng."}]', '[{"phrase":"travel abroad"},{"phrase":"travel around the world"},{"phrase":"travel by train"},{"phrase":"travel a lot"}]', 'Anh: travelled · Mỹ: traveled', '/ˈtrævl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trave/travel__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 4, 'enjoy', 'thích, thưởng thức; tận hưởng', 'verb', '[{"en":"I really enjoy cooking for my friends on weekends.","vi":"Tôi rất thích nấu ăn cho bạn bè vào cuối tuần."},{"en":"Did you enjoy the movie last night?","vi":"Tối qua bạn xem phim có thích không?"},{"en":"Enjoy your vacation, and send us some photos!","vi":"Chúc bạn tận hưởng kỳ nghỉ, nhớ gửi cho chúng tôi vài tấm ảnh nhé!"}]', '[{"phrase":"enjoy yourself"},{"phrase":"really enjoy"},{"phrase":"enjoy doing something"},{"phrase":"enjoy your meal"}]', 'enjoy + V-ing (enjoy reading)', '/ɪnˈdʒɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enj/enjoy/enjoy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 5, 'death', 'cái chết; sự qua đời', 'noun', '[{"en":"Smoking is a major cause of death in many countries.","vi":"Hút thuốc là một nguyên nhân gây tử vong hàng đầu ở nhiều nước."},{"en":"After his wife''s death, he moved closer to his children.","vi":"Sau khi vợ mất, ông ấy chuyển đến sống gần các con hơn."},{"en":"Nobody knows the exact date of the writer''s death.","vi":"Không ai biết chính xác ngày mất của nhà văn."}]', '[{"phrase":"cause of death"},{"phrase":"life and death"},{"phrase":"sudden death"},{"phrase":"after his death"}]', 'die (v) – dead (adj) – death (n)', '/deθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/death/death__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 6, 'nice', 'đẹp, dễ chịu; tốt bụng, tử tế', 'adjective', '[{"en":"It''s a nice day, so let''s have lunch outside.","vi":"Hôm nay trời đẹp, mình ăn trưa ngoài trời đi."},{"en":"Our new neighbors are really nice people.","vi":"Hàng xóm mới của chúng tôi là những người rất tốt bụng."},{"en":"It was nice of you to help me with my bags.","vi":"Bạn thật tử tế khi giúp tôi mang túi."}]', '[{"phrase":"nice to meet you"},{"phrase":"have a nice day"},{"phrase":"nice of you"},{"phrase":"really nice"}]', NULL, '/naɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nic/nice_/nice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 7, 'amount', 'lượng, số lượng; số tiền', 'noun', '[{"en":"You should drink a large amount of water in hot weather.","vi":"Bạn nên uống nhiều nước khi trời nóng."},{"en":"The total amount on the bill was higher than we expected.","vi":"Tổng số tiền trên hóa đơn cao hơn chúng tôi dự tính."},{"en":"She spends a huge amount of time on her phone.","vi":"Cô ấy dành rất nhiều thời gian cho điện thoại."}]', '[{"phrase":"a large amount of"},{"phrase":"a small amount of"},{"phrase":"total amount"},{"phrase":"amount of time"}]', 'amount of + danh từ không đếm được (money, time)', '/əˈmaʊnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amo/amoun/amount__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 8, 'improve', 'cải thiện; tiến bộ', 'verb', '[{"en":"I watch English movies to improve my listening skills.","vi":"Tôi xem phim tiếng Anh để cải thiện kỹ năng nghe."},{"en":"His health has improved a lot since he started exercising.","vi":"Sức khỏe của anh ấy đã cải thiện nhiều từ khi bắt đầu tập thể dục."},{"en":"Your writing is improving every week, so keep practicing.","vi":"Bài viết của bạn tiến bộ từng tuần, cứ tiếp tục luyện tập nhé."}]', '[{"phrase":"improve skills"},{"phrase":"greatly improve"},{"phrase":"improve the quality"},{"phrase":"improve your English"}]', NULL, '/ɪmˈpruːv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impro/improve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 9, 'picture', 'bức tranh, bức ảnh; hình dung', 'noun', '[{"en":"Can you take a picture of us in front of the lake?","vi":"Bạn chụp giúp chúng tôi một tấm ảnh trước hồ được không?"},{"en":"There is a beautiful picture of the sea on the wall.","vi":"Trên tường có một bức tranh biển rất đẹp."},{"en":"This book gives a clear picture of life in the countryside.","vi":"Cuốn sách này cho ta một hình dung rõ ràng về cuộc sống ở nông thôn."}]', '[{"phrase":"take a picture"},{"phrase":"draw a picture"},{"phrase":"clear picture"},{"phrase":"paint a picture"}]', NULL, '/ˈpɪktʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pic/pictu/picture__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 10, 'boy', 'cậu bé, con trai', 'noun', '[{"en":"The little boy is playing with his dog in the yard.","vi":"Cậu bé đang chơi với con chó của mình ngoài sân."},{"en":"They have two boys and a girl.","vi":"Họ có hai con trai và một con gái."},{"en":"When I was a boy, I walked to school every day.","vi":"Hồi còn nhỏ, ngày nào tôi cũng đi bộ đến trường."}]', '[{"phrase":"little boy"},{"phrase":"baby boy"},{"phrase":"teenage boy"},{"phrase":"boys and girls"}]', NULL, '/bɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boy/boy__/boy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 11, 'regard', 'coi (là), xem (như); đánh giá', 'verb', '[{"en":"Many people regard her as the best teacher in the school.","vi":"Nhiều người coi cô ấy là giáo viên giỏi nhất trường."},{"en":"This area was once regarded as unsafe at night.","vi":"Khu này từng bị xem là không an toàn vào ban đêm."},{"en":"My parents have always regarded education as very important.","vi":"Bố mẹ tôi luôn coi việc học là rất quan trọng."}]', '[{"phrase":"regard as"},{"phrase":"widely regarded"},{"phrase":"highly regarded"},{"phrase":"with regard to"}]', 'regard somebody/something as ... (coi ai/cái gì là ...)', '/rɪˈɡɑːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regar/regard__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 12, 'organization', 'tổ chức; sự sắp xếp', 'noun', '[{"en":"She works for an organization that helps homeless families.","vi":"Cô ấy làm việc cho một tổ chức giúp đỡ các gia đình vô gia cư."},{"en":"Many organizations offer free English classes for adults.","vi":"Nhiều tổ chức mở lớp tiếng Anh miễn phí cho người lớn."},{"en":"Good organization will help you finish the project on time.","vi":"Sắp xếp tốt sẽ giúp bạn hoàn thành dự án đúng hạn."}]', '[{"phrase":"non-profit organization"},{"phrase":"international organization"},{"phrase":"charity organization"},{"phrase":"work for an organization"}]', 'Anh: organisation · Mỹ: organization', '/ˌɔːrɡənəˈzeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organization__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 13, 'happy', 'vui, hạnh phúc; hài lòng; sẵn lòng', 'adjective', '[{"en":"The children were very happy to see their grandparents.","vi":"Bọn trẻ rất vui khi gặp ông bà."},{"en":"Are you happy with your new apartment?","vi":"Bạn có hài lòng với căn hộ mới không?"},{"en":"I''m happy to help if you need anything.","vi":"Nếu bạn cần gì, tôi sẵn lòng giúp."}]', '[{"phrase":"happy birthday"},{"phrase":"happy with"},{"phrase":"happy to help"},{"phrase":"make someone happy"}]', NULL, '/ˈhæpi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happy/happy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 14, 'couple', 'cặp, đôi (vợ chồng, người yêu); vài', 'noun', '[{"en":"A young couple just moved into the house next door.","vi":"Một cặp vợ chồng trẻ vừa chuyển đến ngôi nhà bên cạnh."},{"en":"Can you wait a couple of minutes?","vi":"Bạn đợi vài phút được không?"},{"en":"We went to the beach a couple of times last summer.","vi":"Mùa hè năm ngoái chúng tôi đi biển vài lần."}]', '[{"phrase":"a couple of"},{"phrase":"young couple"},{"phrase":"married couple"},{"phrase":"elderly couple"}]', 'a couple of = hai hoặc vài', '/ˈkʌpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/coupl/couple__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 15, 'act', 'hành động; cư xử; đóng vai', 'verb', '[{"en":"We need to act quickly before the problem gets worse.","vi":"Chúng ta cần hành động nhanh trước khi vấn đề trở nên tệ hơn."},{"en":"Stop acting like a child and listen to me.","vi":"Đừng cư xử như trẻ con nữa và nghe tôi nói đây."},{"en":"She acted in several school plays when she was young.","vi":"Hồi nhỏ cô ấy từng diễn trong vài vở kịch ở trường."}]', '[{"phrase":"act quickly"},{"phrase":"act like"},{"phrase":"act as"},{"phrase":"act fast"}]', NULL, '/ækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/act__/act__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 16, 'range', 'loạt, nhiều loại; phạm vi, khoảng', 'noun', '[{"en":"The shop sells a wide range of shoes for children.","vi":"Cửa hàng bán rất nhiều loại giày cho trẻ em."},{"en":"This apartment is out of our price range.","vi":"Căn hộ này vượt quá khoảng giá chúng tôi có thể chi trả."},{"en":"Most of the students in this class are in the 12 to 15 age range.","vi":"Phần lớn học sinh lớp này ở độ tuổi từ 12 đến 15."}]', '[{"phrase":"a wide range of"},{"phrase":"price range"},{"phrase":"age range"},{"phrase":"range of products"}]', NULL, '/reɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/range/range__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 17, 'quality', 'chất lượng; phẩm chất', 'noun', '[{"en":"The food here is cheap, but the quality is excellent.","vi":"Đồ ăn ở đây rẻ nhưng chất lượng rất tuyệt."},{"en":"Regular exercise can improve your quality of life.","vi":"Tập thể dục đều đặn có thể nâng cao chất lượng cuộc sống của bạn."},{"en":"Patience is an important quality for a teacher.","vi":"Sự kiên nhẫn là một phẩm chất quan trọng của giáo viên."}]', '[{"phrase":"high quality"},{"phrase":"quality of life"},{"phrase":"good quality"},{"phrase":"poor quality"}]', NULL, '/ˈkwɑːləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/quality__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 18, 'project', 'dự án; đề tài, bài tập lớn', 'noun', '[{"en":"Our team is working on a new project this month.","vi":"Tháng này nhóm chúng tôi đang làm một dự án mới."},{"en":"The city started a project to build more parks.","vi":"Thành phố đã khởi động một dự án xây thêm công viên."},{"en":"I have to finish my science project by Friday.","vi":"Tôi phải hoàn thành bài tập lớn môn khoa học trước thứ Sáu."}]', '[{"phrase":"work on a project"},{"phrase":"research project"},{"phrase":"school project"},{"phrase":"project manager"}]', NULL, '/ˈprɑːdʒekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proje/project__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 19, 'round', 'vòng, hiệp; lượt, chầu; ván', 'noun', '[{"en":"Our team won the first round of the competition.","vi":"Đội chúng tôi đã thắng vòng đầu tiên của cuộc thi."},{"en":"After the meal, he bought a round of drinks for everyone.","vi":"Sau bữa ăn, anh ấy mời mọi người một chầu đồ uống."},{"en":"We played another round of cards after dinner.","vi":"Sau bữa tối chúng tôi chơi thêm một ván bài."}]', '[{"phrase":"first round"},{"phrase":"final round"},{"phrase":"a round of drinks"},{"phrase":"round of applause"}]', 'Cũng là tính từ: round (tròn) – a round table', '/raʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/round/round__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 20, 'opportunity', 'cơ hội, dịp', 'noun', '[{"en":"Studying abroad is a great opportunity to learn a new language.","vi":"Du học là cơ hội tuyệt vời để học một ngôn ngữ mới."},{"en":"I''d like to take this opportunity to thank all of you.","vi":"Tôi muốn nhân dịp này cảm ơn tất cả các bạn."},{"en":"She never missed an opportunity to practice her English.","vi":"Cô ấy chưa bao giờ bỏ lỡ cơ hội luyện tiếng Anh."}]', '[{"phrase":"take the opportunity"},{"phrase":"great opportunity"},{"phrase":"job opportunity"},{"phrase":"miss an opportunity"}]', NULL, '/ˌɑːpərˈtuːnəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppor/opportunity__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 21, 'road', 'con đường, đường (xe chạy)', 'noun', '[{"en":"Be careful when you cross the road.","vi":"Cẩn thận khi bạn băng qua đường nhé."},{"en":"The road to the village was narrow and full of holes.","vi":"Con đường vào làng hẹp và đầy ổ gà."},{"en":"We spent three days on the road during our trip.","vi":"Chúng tôi đã đi đường mất ba ngày trong chuyến đi."}]', '[{"phrase":"cross the road"},{"phrase":"main road"},{"phrase":"on the road"},{"phrase":"road trip"}]', NULL, '/rəʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roa/road_/road__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 22, 'accord', 'theo; tự nguyện', 'verb', '[{"en":"According to the weather forecast, it will rain tomorrow.","vi":"Theo dự báo thời tiết, ngày mai trời sẽ mưa."},{"en":"Everything went according to plan, so we finished early.","vi":"Mọi việc diễn ra theo đúng kế hoạch nên chúng tôi xong sớm."},{"en":"Nobody asked him to leave; he left of his own accord.","vi":"Không ai bảo anh ấy đi cả; anh ấy tự nguyện rời đi."}]', '[{"phrase":"according to"},{"phrase":"according to plan"},{"phrase":"of your own accord"}]', 'Thường gặp: according to (theo) · of your own accord (tự nguyện)', '/əˈkɔːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accor/accord__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 23, 'list', 'danh sách', 'noun', '[{"en":"Don''t forget to bring the shopping list to the supermarket.","vi":"Đừng quên mang danh sách đồ cần mua đến siêu thị nhé."},{"en":"Is my name on the list for the trip?","vi":"Tên tôi có trong danh sách đi chuyến đi không?"},{"en":"She made a list of things to do before the wedding.","vi":"Cô ấy lập danh sách những việc cần làm trước đám cưới."}]', '[{"phrase":"make a list"},{"phrase":"shopping list"},{"phrase":"on the list"},{"phrase":"waiting list"}]', NULL, '/lɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/list_/list__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 24, 'wish', 'ước; chúc; muốn', 'verb', '[{"en":"I wish I could speak English as well as you.","vi":"Ước gì tôi nói tiếng Anh giỏi được như bạn."},{"en":"We wish you a happy new year!","vi":"Chúc bạn năm mới vui vẻ!"},{"en":"You may leave early if you wish.","vi":"Nếu muốn, bạn có thể về sớm."}]', '[{"phrase":"wish someone luck"},{"phrase":"make a wish"},{"phrase":"best wishes"},{"phrase":"if you wish"}]', 'I wish + quá khứ (ước điều không có thật ở hiện tại)', '/wɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wis/wish_/wish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 25, 'therefore', 'vì vậy, do đó', 'adverb', '[{"en":"The bridge was closed, and therefore we had to take another road.","vi":"Cây cầu bị đóng nên chúng tôi phải đi đường khác."},{"en":"She is only sixteen and therefore cannot drive a car.","vi":"Cô ấy mới mười sáu tuổi, do đó chưa được lái ô tô."},{"en":"Prices went up last year; therefore, many families spent less.","vi":"Năm ngoái giá cả tăng, vì vậy nhiều gia đình đã chi tiêu ít hơn."}]', '[{"phrase":"and therefore"},{"phrase":"is therefore"}]', 'Trang trọng hơn so; hay đứng sau dấu chấm phẩy hoặc and', '/ˈðerfɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/therefore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 26, 'wear', 'mặc; đeo, đội; mang (giày)', 'verb', '[{"en":"You should wear a coat because it''s cold outside.","vi":"Bạn nên mặc áo khoác vì bên ngoài trời lạnh."},{"en":"My brother has worn glasses since he was ten.","vi":"Anh trai tôi đeo kính từ năm mười tuổi."},{"en":"Everyone must wear a helmet when riding a motorbike.","vi":"Mọi người phải đội mũ bảo hiểm khi đi xe máy."}]', '[{"phrase":"wear glasses"},{"phrase":"wear a helmet"},{"phrase":"wear a seat belt"},{"phrase":"wear makeup"}]', 'wear – wore – worn', '/wer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wear_/wear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 27, 'fund', 'quỹ; tiền, kinh phí', 'noun', '[{"en":"The school is raising funds to build a new library.","vi":"Trường đang gây quỹ để xây một thư viện mới."},{"en":"We started a fund to help families after the flood.","vi":"Chúng tôi lập một quỹ để giúp các gia đình sau trận lũ."},{"en":"The project stopped because it ran out of funds.","vi":"Dự án phải dừng lại vì hết kinh phí."}]', '[{"phrase":"raise funds"},{"phrase":"run out of funds"},{"phrase":"set up a fund"},{"phrase":"public funds"}]', 'Nghĩa tiền/kinh phí thường dùng số nhiều: funds', '/fʌnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fund_/fund__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 28, 'rest', 'sự nghỉ ngơi; phần còn lại', 'noun', '[{"en":"You look tired, so why don''t you get some rest?","vi":"Trông bạn mệt đấy, sao không nghỉ ngơi một chút?"},{"en":"Let''s take a short rest before we climb the hill.","vi":"Mình nghỉ một lát trước khi leo đồi nhé."},{"en":"I''ll eat half now and save the rest for later.","vi":"Tôi sẽ ăn một nửa bây giờ và để dành phần còn lại cho lát nữa."}]', '[{"phrase":"get some rest"},{"phrase":"take a rest"},{"phrase":"the rest of"},{"phrase":"rest of the day"}]', NULL, '/rest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/rest_/rest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-01', 29, 'kid', 'đứa trẻ; con (thân mật)', 'noun', '[{"en":"The kids are playing football in the park.","vi":"Bọn trẻ đang đá bóng trong công viên."},{"en":"How many kids do you have?","vi":"Bạn có mấy đứa con?"},{"en":"When I was a kid, I wanted to be a pilot.","vi":"Hồi còn nhỏ, tôi muốn trở thành phi công."}]', '[{"phrase":"have kids"},{"phrase":"little kid"},{"phrase":"school kids"},{"phrase":"when I was a kid"}]', 'Thân mật, dùng trong văn nói; trang trọng hơn: child', '/kɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kid/kid__/kid__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-02', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 2', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 1, 'industry', 'ngành công nghiệp; ngành', 'noun', '[{"en":"My father has worked in the car industry for twenty years.","vi":"Bố tôi đã làm trong ngành công nghiệp ô tô được hai mươi năm."},{"en":"Tourism is the most important industry on this island.","vi":"Du lịch là ngành quan trọng nhất trên hòn đảo này."},{"en":"She wants to find a job in the music industry.","vi":"Cô ấy muốn tìm việc trong ngành âm nhạc."}]', '[{"phrase":"car industry"},{"phrase":"music industry"},{"phrase":"tourism industry"}]', NULL, '/ˈɪndəstri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indus/industry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 2, 'education', 'giáo dục; học vấn', 'noun', '[{"en":"Many parents spend a lot of money on their children''s education.","vi":"Nhiều phụ huynh chi rất nhiều tiền cho việc học của con cái."},{"en":"She was the first person in her family to get a university education.","vi":"Cô ấy là người đầu tiên trong gia đình được học đại học."},{"en":"He left school at sixteen but continued his education later in life.","vi":"Anh ấy nghỉ học năm mười sáu tuổi nhưng sau này vẫn tiếp tục học lên."}]', '[{"phrase":"higher education"},{"phrase":"university education"},{"phrase":"get an education"}]', NULL, '/ˌedʒuˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/education__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 3, 'measure', 'đo; đánh giá', 'verb', '[{"en":"The nurse measured my height and weight.","vi":"Y tá đo chiều cao và cân nặng của tôi."},{"en":"Can you measure the window before we buy new curtains?","vi":"Bạn đo cửa sổ giúp mình trước khi chúng ta mua rèm mới được không?"},{"en":"It is hard to measure how much students really learn.","vi":"Rất khó đánh giá học sinh thực sự học được bao nhiêu."}]', '[{"phrase":"measure the size"},{"phrase":"measure progress"},{"phrase":"measure success"}]', NULL, '/ˈmeʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/measu/measure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 4, 'kill', 'giết; làm chết', 'verb', '[{"en":"The cold winter killed most of the plants in our garden.","vi":"Mùa đông lạnh giá đã làm chết gần hết cây trong vườn nhà tôi."},{"en":"We played cards to kill time while waiting for the train.","vi":"Chúng tôi chơi bài để giết thời gian trong lúc chờ tàu."},{"en":"Our cat killed a mouse in the kitchen last night.","vi":"Tối qua con mèo nhà tôi đã giết một con chuột trong bếp."}]', '[{"phrase":"kill time"},{"phrase":"be killed in an accident"},{"phrase":"kill insects"}]', NULL, '/kɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kil/kill_/kill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 5, 'serve', 'phục vụ; dọn (món ăn)', 'verb', '[{"en":"The restaurant serves breakfast until eleven o''clock.","vi":"Nhà hàng phục vụ bữa sáng đến mười một giờ."},{"en":"Dinner will be served in the main hall at seven.","vi":"Bữa tối sẽ được dọn ra ở sảnh chính lúc bảy giờ."},{"en":"The waiter who served us was very friendly.","vi":"Anh bồi bàn phục vụ chúng tôi rất thân thiện."}]', '[{"phrase":"serve breakfast"},{"phrase":"serve food"},{"phrase":"serve customers"}]', NULL, '/sɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serve/serve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 6, 'likely', 'có khả năng; có thể xảy ra', 'adjective', '[{"en":"It''s likely to rain this afternoon, so take an umbrella.","vi":"Chiều nay có khả năng mưa, nên hãy mang theo ô."},{"en":"Young drivers are more likely to have accidents.","vi":"Tài xế trẻ có nhiều khả năng gặp tai nạn hơn."},{"en":"It seems very likely that the shop will close next year.","vi":"Có vẻ rất có khả năng cửa hàng sẽ đóng cửa vào năm sau."}]', '[{"phrase":"be likely to"},{"phrase":"more likely"},{"phrase":"very likely"}]', 'be likely to + V: có khả năng sẽ…', '/ˈlaɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/likel/likely__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 7, 'certainly', 'chắc chắn; tất nhiên', 'adverb', '[{"en":"She will almost certainly pass the exam next week.","vi":"Gần như chắc chắn cô ấy sẽ đỗ kỳ thi vào tuần tới."},{"en":"You can certainly bring your sister to the party.","vi":"Tất nhiên bạn có thể dẫn em gái đến bữa tiệc."},{"en":"It was certainly the best meal I''ve had this year.","vi":"Đó chắc chắn là bữa ăn ngon nhất tôi được ăn trong năm nay."}]', '[{"phrase":"almost certainly"},{"phrase":"certainly not"},{"phrase":"most certainly"}]', NULL, '/ˈsɜːrtnli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/certa/certainly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 8, 'national', '(thuộc) quốc gia; toàn quốc', 'adjective', '[{"en":"Schools are closed today because it is a national holiday.","vi":"Hôm nay các trường học nghỉ vì là ngày lễ quốc gia."},{"en":"The story was reported on national television.","vi":"Câu chuyện được đưa tin trên truyền hình quốc gia."},{"en":"He was chosen to play for the national team at eighteen.","vi":"Anh ấy được chọn vào đội tuyển quốc gia khi mới mười tám tuổi."}]', '[{"phrase":"national holiday"},{"phrase":"national team"},{"phrase":"national park"},{"phrase":"national television"}]', NULL, '/ˈnæʃnəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natio/national__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 9, 'teach', 'dạy; giảng dạy', 'verb', '[{"en":"My mother teaches math at a high school.","vi":"Mẹ tôi dạy toán ở một trường cấp ba."},{"en":"Who taught you to swim when you were little?","vi":"Ai đã dạy bạn bơi khi bạn còn nhỏ?"},{"en":"He has taught English in Vietnam for five years.","vi":"Anh ấy đã dạy tiếng Anh ở Việt Nam được năm năm."}]', '[{"phrase":"teach English"},{"phrase":"teach children"},{"phrase":"teach a class"}]', 'teach – taught – taught', '/tiːtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/teach/teach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 10, 'field', 'cánh đồng; sân (thể thao); lĩnh vực', 'noun', '[{"en":"Cows were eating grass in the field next to the road.","vi":"Những con bò đang ăn cỏ trên cánh đồng cạnh con đường."},{"en":"The players ran onto the field before the game started.","vi":"Các cầu thủ chạy ra sân trước khi trận đấu bắt đầu."},{"en":"She is an expert in the field of medicine.","vi":"Cô ấy là chuyên gia trong lĩnh vực y học."}]', '[{"phrase":"football field"},{"phrase":"in the field of"},{"phrase":"field of study"}]', NULL, '/fiːld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fie/field/field__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 11, 'security', 'an ninh; sự an toàn', 'noun', '[{"en":"We had to go through security at the airport.","vi":"Chúng tôi phải qua cửa kiểm tra an ninh ở sân bay."},{"en":"The building has cameras at every door for extra security.","vi":"Tòa nhà có camera ở mọi cửa để tăng cường an ninh."},{"en":"A stable job gives my family a sense of security.","vi":"Một công việc ổn định mang lại cho gia đình tôi cảm giác an toàn."}]', '[{"phrase":"airport security"},{"phrase":"security guard"},{"phrase":"job security"},{"phrase":"sense of security"}]', 'không đếm được', '/sɪˈkjʊrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/security__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 12, 'air', 'không khí; không trung', 'noun', '[{"en":"Let''s open the window to get some fresh air.","vi":"Mình mở cửa sổ cho có chút không khí trong lành nhé."},{"en":"The air in big cities is often very dirty.","vi":"Không khí ở các thành phố lớn thường rất bẩn."},{"en":"The children threw their hats into the air.","vi":"Bọn trẻ tung mũ lên không trung."}]', '[{"phrase":"fresh air"},{"phrase":"air pollution"},{"phrase":"into the air"},{"phrase":"by air"}]', 'không đếm được', '/er/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/air__/air__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 13, 'benefit', 'lợi ích; phúc lợi', 'noun', '[{"en":"Regular exercise has many benefits for your health.","vi":"Tập thể dục thường xuyên có nhiều lợi ích cho sức khỏe."},{"en":"One benefit of living here is the short walk to work.","vi":"Một lợi ích khi sống ở đây là chỉ cần đi bộ một đoạn ngắn là đến chỗ làm."},{"en":"The job offers good pay and health benefits.","vi":"Công việc này có lương tốt và phúc lợi y tế."}]', '[{"phrase":"health benefits"},{"phrase":"many benefits"},{"phrase":"the benefit of"}]', NULL, '/ˈbenɪfɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benef/benefit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 14, 'trade', 'thương mại; sự buôn bán; nghề', 'noun', '[{"en":"Trade between the two countries has grown quickly.","vi":"Thương mại giữa hai nước đã tăng trưởng nhanh chóng."},{"en":"The town grew rich from the fish trade.","vi":"Thị trấn trở nên giàu có nhờ nghề buôn bán cá."},{"en":"My uncle learned a trade instead of going to university.","vi":"Chú tôi đi học nghề thay vì vào đại học."}]', '[{"phrase":"international trade"},{"phrase":"trade between"},{"phrase":"learn a trade"}]', NULL, '/treɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trade/trade__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 15, 'risk', 'rủi ro; nguy cơ', 'noun', '[{"en":"Smoking increases the risk of heart disease.","vi":"Hút thuốc làm tăng nguy cơ mắc bệnh tim."},{"en":"Starting your own business is always a big risk.","vi":"Tự mở doanh nghiệp riêng luôn là một rủi ro lớn."},{"en":"I don''t want to take any risks with my money.","vi":"Tôi không muốn chấp nhận bất kỳ rủi ro nào với tiền của mình."}]', '[{"phrase":"take a risk"},{"phrase":"the risk of"},{"phrase":"high risk"},{"phrase":"at risk"}]', NULL, '/rɪsk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ris/risk_/risk__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 16, 'news', 'tin tức; tin', 'noun', '[{"en":"I have some good news for you!","vi":"Mình có tin vui cho bạn đây!"},{"en":"My dad watches the news every evening after dinner.","vi":"Bố tôi xem thời sự mỗi tối sau bữa ăn."},{"en":"Have you heard the news about the new manager?","vi":"Bạn đã nghe tin về người quản lý mới chưa?"}]', '[{"phrase":"good news"},{"phrase":"bad news"},{"phrase":"watch the news"},{"phrase":"hear the news"}]', 'không đếm được, dùng động từ số ít: The news is…', '/nuːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/news_/news__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 17, 'standard', 'tiêu chuẩn; mức, trình độ', 'noun', '[{"en":"This restaurant has very high standards of service.","vi":"Nhà hàng này có tiêu chuẩn phục vụ rất cao."},{"en":"Her English is of a very high standard.","vi":"Tiếng Anh của cô ấy ở trình độ rất cao."},{"en":"The standard of living in the city has improved a lot.","vi":"Mức sống ở thành phố đã được cải thiện nhiều."}]', '[{"phrase":"high standards"},{"phrase":"standard of living"},{"phrase":"safety standards"}]', NULL, '/ˈstændərd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stand/standard__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 18, 'vote', 'bỏ phiếu; biểu quyết', 'verb', '[{"en":"The students voted for a new class president.","vi":"Học sinh đã bỏ phiếu bầu lớp trưởng mới."},{"en":"Let''s vote on where to go for our team dinner.","vi":"Mình biểu quyết xem cả nhóm đi đâu ăn tối nhé."},{"en":"Most people in the club voted against changing the meeting time.","vi":"Phần lớn thành viên câu lạc bộ bỏ phiếu phản đối việc đổi giờ họp."}]', '[{"phrase":"vote for"},{"phrase":"vote against"},{"phrase":"vote on"}]', NULL, '/vəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vot/vote_/vote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 19, 'percent', 'phần trăm', 'noun', '[{"en":"About ninety percent of the students passed the test.","vi":"Khoảng chín mươi phần trăm học sinh đã qua bài kiểm tra."},{"en":"The shop is offering twenty percent off all shoes this week.","vi":"Tuần này cửa hàng giảm hai mươi phần trăm cho tất cả giày dép."},{"en":"Prices have gone up by five percent since last year.","vi":"Giá cả đã tăng năm phần trăm kể từ năm ngoái."}]', '[{"phrase":"percent of"},{"phrase":"twenty percent off"},{"phrase":"ninety percent"}]', 'Anh: per cent · Mỹ: percent', '/pərˈsɛnt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 20, 'focus', 'tập trung', 'verb', '[{"en":"I can''t focus on my work with all this noise.","vi":"Ồn ào thế này tôi không thể tập trung làm việc được."},{"en":"This year the company will focus on online sales.","vi":"Năm nay công ty sẽ tập trung vào bán hàng trực tuyến."},{"en":"Try to focus on the road when you are driving.","vi":"Khi lái xe, hãy cố tập trung nhìn đường."}]', '[{"phrase":"focus on"},{"phrase":"focus attention on"},{"phrase":"stay focused"}]', 'focus on + N/V-ing', '/ˈfəʊkəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foc/focus/focus__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 21, 'stage', 'giai đoạn; sân khấu', 'noun', '[{"en":"The project is still in its early stages.","vi":"Dự án vẫn đang ở giai đoạn đầu."},{"en":"At this stage, we don''t know the cause of the problem.","vi":"Ở giai đoạn này, chúng tôi chưa biết nguyên nhân của vấn đề."},{"en":"The band walked onto the stage and the crowd cheered.","vi":"Ban nhạc bước lên sân khấu và đám đông reo hò."}]', '[{"phrase":"early stage"},{"phrase":"at this stage"},{"phrase":"on stage"},{"phrase":"final stage"}]', NULL, '/steɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stage/stage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 22, 'space', 'chỗ trống; không gian; vũ trụ', 'noun', '[{"en":"There isn''t enough space in the car for all our bags.","vi":"Trong xe không đủ chỗ cho tất cả túi đồ của chúng ta."},{"en":"Children need plenty of open space to play.","vi":"Trẻ em cần nhiều không gian rộng rãi để vui chơi."},{"en":"She dreams of traveling into space one day.","vi":"Cô ấy mơ một ngày nào đó được bay vào vũ trụ."}]', '[{"phrase":"enough space"},{"phrase":"parking space"},{"phrase":"open space"},{"phrase":"outer space"}]', NULL, '/speɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spa/space/space__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 23, 'instead', 'thay vào đó; thay vì', 'adverb', '[{"en":"We didn''t have time to cook, so we ordered pizza instead.","vi":"Chúng tôi không có thời gian nấu ăn nên đã gọi pizza thay vào đó."},{"en":"Why don''t you walk to school instead of taking the bus?","vi":"Sao bạn không đi bộ đến trường thay vì đi xe buýt?"},{"en":"Instead of watching TV all evening, she read a book.","vi":"Thay vì xem TV cả buổi tối, cô ấy đọc một cuốn sách."}]', '[{"phrase":"instead of"},{"phrase":"instead of taking"},{"phrase":"order something instead"}]', 'instead of + N/V-ing', '/ɪnˈsted/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inste/instead__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 24, 'realize', 'nhận ra; thực hiện (ước mơ)', 'verb', '[{"en":"I didn''t realize how late it was until I checked my phone.","vi":"Mãi đến khi xem điện thoại tôi mới nhận ra đã muộn đến thế."},{"en":"She suddenly realized that she had left her keys at home.","vi":"Cô ấy chợt nhận ra mình đã để quên chìa khóa ở nhà."},{"en":"He worked hard for years to realize his dream of becoming a pilot.","vi":"Anh ấy đã làm việc chăm chỉ nhiều năm để thực hiện ước mơ trở thành phi công."}]', '[{"phrase":"suddenly realize"},{"phrase":"realize a dream"},{"phrase":"come to realize"}]', 'Anh: realise · Mỹ: realize', '/ˈriːəlaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reali/realize__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 25, 'usually', 'thường; thông thường', 'adverb', '[{"en":"I usually get up at six on weekdays.","vi":"Tôi thường dậy lúc sáu giờ vào các ngày trong tuần."},{"en":"The bus is usually late when it rains.","vi":"Xe buýt thường đến muộn khi trời mưa."},{"en":"What do you usually have for breakfast?","vi":"Bạn thường ăn gì vào bữa sáng?"}]', '[{"phrase":"usually get up"},{"phrase":"don''t usually"},{"phrase":"usually have"}]', NULL, '/ˈjuːʒuəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/usu/usual/usually__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 26, 'data', 'dữ liệu; số liệu', 'noun', '[{"en":"We collected data from over five hundred students.","vi":"Chúng tôi đã thu thập dữ liệu từ hơn năm trăm sinh viên."},{"en":"Make sure you back up your data before updating your phone.","vi":"Hãy nhớ sao lưu dữ liệu trước khi cập nhật điện thoại."},{"en":"The data shows that more people are working from home.","vi":"Số liệu cho thấy ngày càng nhiều người làm việc tại nhà."}]', '[{"phrase":"collect data"},{"phrase":"personal data"},{"phrase":"back up data"}]', 'thường dùng như danh từ không đếm được', '/ˈdeɪtə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/data_/data__us_3_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 27, 'single', 'một, duy nhất; độc thân; đơn', 'adjective', '[{"en":"She didn''t make a single mistake on the test.","vi":"Cô ấy không mắc một lỗi nào trong bài kiểm tra."},{"en":"My brother is thirty and still single.","vi":"Anh trai tôi ba mươi tuổi mà vẫn còn độc thân."},{"en":"I''d like to book a single room for two nights.","vi":"Tôi muốn đặt một phòng đơn trong hai đêm."}]', '[{"phrase":"single room"},{"phrase":"every single day"},{"phrase":"single parent"}]', NULL, '/ˈsɪŋɡl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/singl/single__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 28, 'address', 'địa chỉ', 'noun', '[{"en":"Can you write your address on this form?","vi":"Bạn có thể ghi địa chỉ của mình vào tờ đơn này không?"},{"en":"I sent the email to the wrong address.","vi":"Tôi đã gửi email nhầm địa chỉ."},{"en":"We moved last month, so here is our new address.","vi":"Chúng tôi đã chuyển nhà tháng trước, nên đây là địa chỉ mới."}]', '[{"phrase":"email address"},{"phrase":"home address"},{"phrase":"new address"},{"phrase":"wrong address"}]', NULL, '/əˈdres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addre/address__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-02', 29, 'performance', 'màn trình diễn; hiệu quả, thành tích', 'noun', '[{"en":"The band gave an amazing performance last night.","vi":"Tối qua ban nhạc đã có một màn trình diễn tuyệt vời."},{"en":"Her performance at work has improved a lot this year.","vi":"Năm nay hiệu quả công việc của cô ấy đã tiến bộ nhiều."},{"en":"Poor sleep can hurt your performance at school.","vi":"Ngủ kém có thể làm giảm thành tích học tập của bạn."}]', '[{"phrase":"give a performance"},{"phrase":"live performance"},{"phrase":"performance at work"}]', NULL, '/pərˈfɔːrməns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfo/performance__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-03', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 3', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 1, 'chance', 'cơ hội; khả năng', 'noun', '[{"en":"This trip is a great chance to practice your English.","vi":"Chuyến đi này là cơ hội tuyệt vời để luyện tiếng Anh của bạn."},{"en":"I didn''t get a chance to call you yesterday.","vi":"Hôm qua tôi không có dịp gọi cho bạn."},{"en":"There''s a good chance it will rain this afternoon.","vi":"Nhiều khả năng chiều nay trời sẽ mưa."}]', '[{"phrase":"get a chance"},{"phrase":"a good chance"},{"phrase":"second chance"},{"phrase":"by chance"}]', NULL, '/tʃæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chanc/chance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 2, 'accept', 'chấp nhận; nhận', 'verb', '[{"en":"She accepted the job offer without a second thought.","vi":"Cô ấy nhận lời mời làm việc mà không chút do dự."},{"en":"Do you accept credit cards here?","vi":"Ở đây có nhận thẻ tín dụng không?"},{"en":"It took him a long time to accept the truth.","vi":"Anh ấy mất rất lâu mới chấp nhận được sự thật."}]', '[{"phrase":"accept an offer"},{"phrase":"accept an invitation"},{"phrase":"accept responsibility"},{"phrase":"accept the truth"}]', 'accept (chấp nhận) ≠ except (ngoại trừ)', '/əkˈsept/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accep/accept__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 3, 'society', 'xã hội; hội, hiệp hội', 'noun', '[{"en":"Teachers play an important role in our society.","vi":"Giáo viên đóng vai trò quan trọng trong xã hội chúng ta."},{"en":"Modern society depends heavily on the internet.","vi":"Xã hội hiện đại phụ thuộc rất nhiều vào internet."},{"en":"My grandfather joined the local history society last year.","vi":"Năm ngoái ông tôi đã tham gia hội lịch sử địa phương."}]', '[{"phrase":"modern society"},{"phrase":"in society"},{"phrase":"role in society"},{"phrase":"member of society"}]', NULL, '/səˈsaɪəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soc/socie/society__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 4, 'technology', 'công nghệ', 'noun', '[{"en":"New technology has changed the way we work.","vi":"Công nghệ mới đã thay đổi cách chúng ta làm việc."},{"en":"My parents are not very comfortable with technology.","vi":"Bố mẹ tôi không rành công nghệ lắm."},{"en":"The school spends a lot of money on technology every year.","vi":"Mỗi năm trường chi rất nhiều tiền cho công nghệ."}]', '[{"phrase":"new technology"},{"phrase":"modern technology"},{"phrase":"information technology"},{"phrase":"use technology"}]', NULL, '/tekˈnɑːlədʒi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technology__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 5, 'mention', 'nhắc đến, đề cập', 'verb', '[{"en":"She didn''t mention that she was moving to another city.","vi":"Cô ấy không nhắc đến chuyện mình sắp chuyển sang thành phố khác."},{"en":"As I mentioned earlier, the meeting starts at nine.","vi":"Như tôi đã đề cập lúc nãy, cuộc họp bắt đầu lúc chín giờ."},{"en":"Please don''t mention it to anyone else.","vi":"Làm ơn đừng nhắc chuyện này với ai khác nhé."}]', '[{"phrase":"mention it"},{"phrase":"as mentioned"},{"phrase":"briefly mention"},{"phrase":"not to mention"}]', 'Không dùng "mention about" — nói "mention something"', '/ˈmenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menti/mention__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 6, 'choice', 'sự lựa chọn', 'noun', '[{"en":"You made the right choice by staying at home.","vi":"Bạn đã lựa chọn đúng khi ở nhà."},{"en":"We had no choice but to wait for the next train.","vi":"Chúng tôi không còn cách nào khác ngoài việc đợi chuyến tàu tiếp theo."},{"en":"This café has a wide choice of cakes.","vi":"Quán cà phê này có rất nhiều loại bánh để lựa chọn."}]', '[{"phrase":"make a choice"},{"phrase":"have no choice"},{"phrase":"the right choice"},{"phrase":"a wide choice"}]', NULL, '/tʃɔɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choic/choice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 7, 'save', 'tiết kiệm; cứu; lưu', 'verb', '[{"en":"I''m saving money to buy a new laptop.","vi":"Tôi đang tiết kiệm tiền để mua một chiếc máy tính xách tay mới."},{"en":"The firefighters saved a little girl from the burning house.","vi":"Lính cứu hỏa đã cứu một bé gái khỏi ngôi nhà đang cháy."},{"en":"Don''t forget to save the file before you close it.","vi":"Đừng quên lưu tệp trước khi đóng nó."}]', '[{"phrase":"save money"},{"phrase":"save time"},{"phrase":"save a life"},{"phrase":"save a file"}]', NULL, '/seɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sav/save_/save__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 8, 'common', 'phổ biến, thông thường; chung', 'adjective', '[{"en":"Headaches are very common among students during exams.","vi":"Đau đầu rất phổ biến ở học sinh trong mùa thi."},{"en":"It''s a common mistake, so don''t worry about it.","vi":"Đó là một lỗi thường gặp, nên đừng lo."},{"en":"My new roommate and I have a lot in common.","vi":"Tôi và bạn cùng phòng mới có nhiều điểm chung."}]', '[{"phrase":"common mistake"},{"phrase":"common problem"},{"phrase":"in common"},{"phrase":"common sense"}]', NULL, '/ˈkɑːmən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commo/common__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 9, 'culture', 'văn hóa', 'noun', '[{"en":"I love learning about the food and culture of other countries.","vi":"Tôi thích tìm hiểu về ẩm thực và văn hóa của các nước khác."},{"en":"Living abroad helped her understand a different culture.","vi":"Sống ở nước ngoài đã giúp cô ấy hiểu một nền văn hóa khác."},{"en":"This company has a friendly and open work culture.","vi":"Công ty này có văn hóa làm việc thân thiện và cởi mở."}]', '[{"phrase":"local culture"},{"phrase":"different cultures"},{"phrase":"popular culture"},{"phrase":"work culture"}]', NULL, '/ˈkʌltʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/culture__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 10, 'total', 'tổng, tổng cộng; hoàn toàn', 'adjective', '[{"en":"The total cost of the trip was about two thousand dollars.","vi":"Tổng chi phí của chuyến đi vào khoảng hai nghìn đô la."},{"en":"What is the total number of students in your class?","vi":"Tổng số học sinh trong lớp bạn là bao nhiêu?"},{"en":"The party was a total surprise to my mother.","vi":"Bữa tiệc hoàn toàn là một bất ngờ đối với mẹ tôi."}]', '[{"phrase":"total cost"},{"phrase":"total number"},{"phrase":"total amount"},{"phrase":"in total"}]', NULL, '/ˈtəʊtl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tot/total/total__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 11, 'demand', 'nhu cầu; yêu cầu', 'noun', '[{"en":"There is a high demand for nurses in big cities.","vi":"Nhu cầu về y tá ở các thành phố lớn rất cao."},{"en":"Demand for air conditioners goes up every summer.","vi":"Nhu cầu về máy lạnh tăng lên vào mỗi mùa hè."},{"en":"The workers stopped working until the company met their demands.","vi":"Công nhân ngừng làm việc cho đến khi công ty đáp ứng yêu cầu của họ."}]', '[{"phrase":"high demand"},{"phrase":"demand for"},{"phrase":"in demand"},{"phrase":"meet demands"}]', NULL, '/dɪˈmænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/deman/demand__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 12, 'material', 'vật liệu, chất liệu; tài liệu', 'noun', '[{"en":"This jacket is made from a soft, warm material.","vi":"Chiếc áo khoác này được làm từ chất liệu mềm và ấm."},{"en":"They used recycled materials to build the new school.","vi":"Họ đã dùng vật liệu tái chế để xây ngôi trường mới."},{"en":"The teacher gave us some reading materials for the weekend.","vi":"Giáo viên đưa cho chúng tôi một số tài liệu đọc cho cuối tuần."}]', '[{"phrase":"building materials"},{"phrase":"raw materials"},{"phrase":"teaching materials"},{"phrase":"reading materials"}]', NULL, '/məˈtɪriəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mater/material__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 13, 'limit', 'giới hạn', 'noun', '[{"en":"The speed limit on this road is fifty kilometers per hour.","vi":"Tốc độ tối đa trên con đường này là năm mươi ki-lô-mét một giờ."},{"en":"Is there a limit to how many books I can borrow?","vi":"Số sách tôi được mượn có bị giới hạn không?"},{"en":"My patience has its limits, so please be on time.","vi":"Sự kiên nhẫn của tôi cũng có giới hạn, nên làm ơn đến đúng giờ."}]', '[{"phrase":"speed limit"},{"phrase":"time limit"},{"phrase":"age limit"},{"phrase":"limit to"}]', NULL, '/ˈlɪmɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lim/limit/limit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 14, 'listen', 'nghe, lắng nghe', 'verb', '[{"en":"I like to listen to music while I cook.","vi":"Tôi thích nghe nhạc trong lúc nấu ăn."},{"en":"Listen carefully, because I will only say this once.","vi":"Nghe kỹ nhé, vì tôi chỉ nói điều này một lần thôi."},{"en":"My son never listens when I tell him to clean his room.","vi":"Con trai tôi chẳng bao giờ nghe lời khi tôi bảo nó dọn phòng."}]', '[{"phrase":"listen to music"},{"phrase":"listen carefully"},{"phrase":"listen to advice"}]', 'Dùng "listen to" + tân ngữ: listen to the radio', '/ˈlɪsn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/liste/listen__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 15, 'due', 'đến hạn; dự kiến (đến)', 'adjective', '[{"en":"The rent is due on the first day of every month.","vi":"Tiền thuê nhà đến hạn phải trả vào ngày đầu tiên của mỗi tháng."},{"en":"Our homework is due next Friday.","vi":"Bài tập về nhà của chúng tôi phải nộp vào thứ Sáu tới."},{"en":"The next train is due in ten minutes.","vi":"Chuyến tàu tiếp theo dự kiến sẽ đến trong mười phút nữa."}]', '[{"phrase":"due date"},{"phrase":"rent is due"},{"phrase":"due back"},{"phrase":"due to"}]', 'due to = do, bởi vì', '/duː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/due/due__/due__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 16, 'wrong', 'sai; có vấn đề, trục trặc', 'adjective', '[{"en":"Sorry, I think you have the wrong number.","vi":"Xin lỗi, tôi nghĩ bạn gọi nhầm số rồi."},{"en":"Two of my answers on the test were wrong.","vi":"Hai câu trả lời trong bài kiểm tra của tôi bị sai."},{"en":"Something is wrong with my phone; it keeps turning off.","vi":"Điện thoại của tôi có vấn đề gì đó; nó cứ tự tắt."}]', '[{"phrase":"wrong answer"},{"phrase":"wrong number"},{"phrase":"something wrong"},{"phrase":"go wrong"}]', NULL, '/rɔːŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wro/wrong/wrong__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 17, 'foot', 'bàn chân; chân (đồi, núi)', 'noun', '[{"en":"My feet hurt after walking around the city all day.","vi":"Chân tôi đau nhức sau khi đi bộ quanh thành phố cả ngày."},{"en":"We usually go to school on foot.","vi":"Chúng tôi thường đi bộ đến trường."},{"en":"There is a small café at the foot of the hill.","vi":"Có một quán cà phê nhỏ ở chân đồi."}]', '[{"phrase":"on foot"},{"phrase":"left foot"},{"phrase":"bare feet"},{"phrase":"at the foot of"}]', 'Số nhiều bất quy tắc: foot – feet', '/fʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/foot_/foot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 18, 'effort', 'nỗ lực, cố gắng', 'noun', '[{"en":"She made a real effort to be friendly to everyone.","vi":"Cô ấy thực sự cố gắng tỏ ra thân thiện với mọi người."},{"en":"Learning a new language takes a lot of time and effort.","vi":"Học một ngôn ngữ mới cần rất nhiều thời gian và công sức."},{"en":"Thanks for your effort, even though we didn''t win.","vi":"Cảm ơn sự nỗ lực của bạn, dù chúng ta đã không thắng."}]', '[{"phrase":"make an effort"},{"phrase":"a lot of effort"},{"phrase":"time and effort"},{"phrase":"worth the effort"}]', NULL, '/ˈefərt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effor/effort__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 19, 'attention', 'sự chú ý', 'noun', '[{"en":"Please pay attention to the teacher.","vi":"Hãy chú ý nghe giáo viên."},{"en":"The bright red car caught everyone''s attention.","vi":"Chiếc xe màu đỏ rực đã thu hút sự chú ý của mọi người."},{"en":"Small children need a lot of attention from their parents.","vi":"Trẻ nhỏ cần được bố mẹ quan tâm rất nhiều."}]', '[{"phrase":"pay attention to"},{"phrase":"attract attention"},{"phrase":"catch someone''s attention"},{"phrase":"draw attention to"}]', 'Không đếm được', '/əˈtenʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attention__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 20, 'upon', 'trên; ngay khi, lúc', 'preposition', '[{"en":"Once upon a time, there lived a poor farmer.","vi":"Ngày xửa ngày xưa, có một bác nông dân nghèo."},{"en":"Upon arrival, guests will receive a free drink.","vi":"Khi đến nơi, khách sẽ được nhận một đồ uống miễn phí."},{"en":"Snow fell upon the quiet village all night.","vi":"Tuyết rơi trên ngôi làng yên tĩnh suốt đêm."}]', '[{"phrase":"once upon a time"},{"phrase":"depend upon"},{"phrase":"upon arrival"},{"phrase":"based upon"}]', 'Trang trọng hơn "on"', '/əˈpɑːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upo/upon_/upon__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 21, 'check', 'kiểm tra', 'verb', '[{"en":"Can you check if the door is locked?","vi":"Bạn có thể kiểm tra xem cửa đã khóa chưa?"},{"en":"I check my email every morning before work.","vi":"Sáng nào trước khi đi làm tôi cũng kiểm tra email."},{"en":"Always check your answers before you hand in the test.","vi":"Hãy luôn kiểm tra lại đáp án trước khi nộp bài."}]', '[{"phrase":"check your email"},{"phrase":"check the answers"},{"phrase":"double-check"},{"phrase":"check carefully"}]', NULL, '/tʃek/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/check/check__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 22, 'complete', 'hoàn thành; điền đầy đủ', 'verb', '[{"en":"The new bridge will be completed next year.","vi":"Cây cầu mới sẽ được hoàn thành vào năm sau."},{"en":"She completed her degree while working full-time.","vi":"Cô ấy đã hoàn thành chương trình học trong khi vẫn đi làm toàn thời gian."},{"en":"Please complete this form and give it to the receptionist.","vi":"Vui lòng điền đầy đủ mẫu đơn này và đưa cho lễ tân."}]', '[{"phrase":"complete a course"},{"phrase":"complete a form"},{"phrase":"complete a task"},{"phrase":"fully complete"}]', NULL, '/kəmˈpliːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complete__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 23, 'lie', 'nằm; nói dối', 'verb', '[{"en":"I just want to lie on the beach and relax.","vi":"Tôi chỉ muốn nằm trên bãi biển và thư giãn."},{"en":"The cat was lying in the sun all afternoon.","vi":"Con mèo nằm phơi nắng suốt cả buổi chiều."},{"en":"He lied to his parents about where he went.","vi":"Cậu ấy đã nói dối bố mẹ về chỗ mình đi."}]', '[{"phrase":"lie down"},{"phrase":"lie in bed"},{"phrase":"lie to someone"},{"phrase":"tell a lie"}]', 'nằm: lie – lay – lain · nói dối: lie – lied – lied', '/laɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lie/lie__/lie__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 24, 'pick', 'chọn; hái', 'verb', '[{"en":"You can pick any color you like.","vi":"Bạn có thể chọn bất kỳ màu nào bạn thích."},{"en":"We picked strawberries at a farm last weekend.","vi":"Cuối tuần trước chúng tôi đã hái dâu ở một trang trại."},{"en":"Our teacher picked me to read the poem aloud.","vi":"Cô giáo đã chọn tôi đọc to bài thơ."}]', '[{"phrase":"pick a number"},{"phrase":"pick a team"},{"phrase":"pick fruit"},{"phrase":"pick flowers"}]', 'pick up = nhặt lên; đón (ai đó)', '/pɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pic/pick_/pick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 25, 'reduce', 'giảm, làm giảm', 'verb', '[{"en":"Walking every day can help reduce stress.","vi":"Đi bộ mỗi ngày có thể giúp giảm căng thẳng."},{"en":"The store has reduced the prices of all winter clothes.","vi":"Cửa hàng đã giảm giá tất cả quần áo mùa đông."},{"en":"We need to reduce the amount of plastic we use.","vi":"Chúng ta cần giảm lượng nhựa mà mình sử dụng."}]', '[{"phrase":"reduce costs"},{"phrase":"reduce the risk"},{"phrase":"reduce stress"},{"phrase":"greatly reduce"}]', NULL, '/rɪˈduːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/reduc/reduce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 26, 'personal', 'cá nhân, riêng tư', 'adjective', '[{"en":"Please don''t ask me such personal questions.","vi":"Làm ơn đừng hỏi tôi những câu hỏi riêng tư như vậy."},{"en":"Keep your personal information safe when you shop online.","vi":"Hãy giữ an toàn thông tin cá nhân khi bạn mua sắm trực tuyến."},{"en":"In my personal opinion, the first movie was better.","vi":"Theo ý kiến cá nhân tôi, bộ phim đầu tiên hay hơn."}]', '[{"phrase":"personal information"},{"phrase":"personal life"},{"phrase":"personal opinion"},{"phrase":"personal question"}]', NULL, '/ˈpɜːrsənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personal__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 27, 'ground', 'mặt đất; sân, bãi', 'noun', '[{"en":"The ground was still wet after the rain.","vi":"Mặt đất vẫn còn ướt sau cơn mưa."},{"en":"She dropped her keys on the ground.","vi":"Cô ấy làm rơi chìa khóa xuống đất."},{"en":"The children were playing football on the sports ground.","vi":"Bọn trẻ đang đá bóng trên sân thể thao."}]', '[{"phrase":"on the ground"},{"phrase":"fall to the ground"},{"phrase":"wet ground"},{"phrase":"sports ground"}]', NULL, '/ɡraʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/groun/ground__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 28, 'animal', 'động vật, con vật', 'noun', '[{"en":"My daughter wants to work with animals when she grows up.","vi":"Con gái tôi muốn làm việc với động vật khi lớn lên."},{"en":"Many wild animals live in this forest.","vi":"Nhiều loài động vật hoang dã sống trong khu rừng này."},{"en":"Dogs are my favorite animal because they are so loyal.","vi":"Chó là con vật tôi thích nhất vì chúng rất trung thành."}]', '[{"phrase":"wild animals"},{"phrase":"farm animals"},{"phrase":"animal lover"}]', NULL, '/ˈænɪml/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ani/anima/animal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-03', 29, 'arrive', 'đến, tới nơi', 'verb', '[{"en":"What time does your flight arrive in Hanoi?","vi":"Chuyến bay của bạn hạ cánh ở Hà Nội lúc mấy giờ?"},{"en":"We arrived at the hotel late at night.","vi":"Chúng tôi đến khách sạn vào lúc đêm muộn."},{"en":"Your package should arrive within three days.","vi":"Bưu kiện của bạn sẽ đến trong vòng ba ngày."}]', '[{"phrase":"arrive at"},{"phrase":"arrive in"},{"phrase":"arrive home"},{"phrase":"arrive late"}]', 'arrive at + địa điểm nhỏ (sân bay, khách sạn); arrive in + thành phố, quốc gia', '/əˈraɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arriv/arrive__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-04', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 4', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 1, 'patient', 'bệnh nhân; kiên nhẫn', 'noun', '[{"en":"The doctor sees about thirty patients every day.","vi":"Bác sĩ khám cho khoảng ba mươi bệnh nhân mỗi ngày."},{"en":"The nurse brought the patient a glass of water.","vi":"Y tá mang cho bệnh nhân một cốc nước."},{"en":"Please be patient, the bus will be here soon.","vi":"Xin hãy kiên nhẫn, xe buýt sẽ đến ngay thôi."}]', '[{"phrase":"treat a patient"},{"phrase":"hospital patient"},{"phrase":"be patient with"}]', 'patient (n) bệnh nhân · patient (adj) kiên nhẫn', '/ˈpeɪʃnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/patie/patient__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 2, 'current', 'hiện tại; hiện hành; dòng chảy', 'adjective', '[{"en":"What is your current address?","vi":"Địa chỉ hiện tại của bạn là gì?"},{"en":"I''m happy with my current job, so I''m not looking for another.","vi":"Tôi hài lòng với công việc hiện tại nên không tìm việc khác."},{"en":"The current was too strong for us to swim across the river.","vi":"Dòng nước chảy quá mạnh nên chúng tôi không thể bơi qua sông."}]', '[{"phrase":"current situation"},{"phrase":"current address"},{"phrase":"current job"},{"phrase":"strong current"}]', 'current ≠ currant (quả lý chua)', '/ˈkɜːrənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/current__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 3, 'century', 'thế kỷ', 'noun', '[{"en":"This church was built in the sixteenth century.","vi":"Nhà thờ này được xây vào thế kỷ mười sáu."},{"en":"Life has changed a lot over the last century.","vi":"Cuộc sống đã thay đổi rất nhiều trong thế kỷ qua."},{"en":"My grandmother''s house is almost a century old.","vi":"Ngôi nhà của bà tôi đã gần một trăm năm tuổi."}]', '[{"phrase":"the 21st century"},{"phrase":"last century"},{"phrase":"a century ago"},{"phrase":"the next century"}]', 'số nhiều: centuries', '/ˈsentʃəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centu/century__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 4, 'evidence', 'bằng chứng; chứng cứ', 'noun', '[{"en":"There is no evidence that coffee is bad for you.","vi":"Không có bằng chứng nào cho thấy cà phê có hại cho bạn."},{"en":"The police found new evidence in the house.","vi":"Cảnh sát đã tìm thấy chứng cứ mới trong ngôi nhà."},{"en":"Can you give any evidence to support your idea?","vi":"Bạn có thể đưa ra bằng chứng nào để ủng hộ ý kiến của mình không?"}]', '[{"phrase":"find evidence"},{"phrase":"evidence of"},{"phrase":"strong evidence"},{"phrase":"scientific evidence"}]', 'không đếm được: a piece of evidence', '/ˈevɪdəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evide/evidence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 5, 'exist', 'tồn tại; có', 'verb', '[{"en":"Do you think life exists on other planets?","vi":"Bạn có nghĩ sự sống tồn tại trên các hành tinh khác không?"},{"en":"This small village has existed for hundreds of years.","vi":"Ngôi làng nhỏ này đã tồn tại hàng trăm năm."},{"en":"Smartphones didn''t exist when my parents were young.","vi":"Hồi bố mẹ tôi còn trẻ thì chưa có điện thoại thông minh."}]', '[{"phrase":"still exist"},{"phrase":"no longer exist"},{"phrase":"exist in"}]', NULL, '/ɪɡˈzɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exi/exist/exist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 6, 'similar', 'tương tự; giống nhau', 'adjective', '[{"en":"My sister and I have very similar tastes in music.","vi":"Chị tôi và tôi có gu âm nhạc rất giống nhau."},{"en":"Your bag is similar to the one I lost.","vi":"Túi của bạn giống cái túi tôi đã làm mất."},{"en":"We had a similar problem at work last year.","vi":"Năm ngoái ở chỗ làm chúng tôi cũng gặp một vấn đề tương tự."}]', '[{"phrase":"similar to"},{"phrase":"very similar"},{"phrase":"similar problem"},{"phrase":"in a similar way"}]', 'đi với giới từ to: similar to', '/ˈsɪmələr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similar__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 7, 'fight', 'đánh nhau; chiến đấu; đấu tranh', 'verb', '[{"en":"The two boys were fighting over a football.","vi":"Hai cậu bé đang đánh nhau để giành một quả bóng."},{"en":"Doctors are working hard to fight the disease.","vi":"Các bác sĩ đang nỗ lực chống lại căn bệnh."},{"en":"Workers fought for better pay and shorter hours.","vi":"Công nhân đã đấu tranh đòi lương cao hơn và giờ làm ngắn hơn."}]', '[{"phrase":"fight for"},{"phrase":"fight against"},{"phrase":"fight a disease"},{"phrase":"fight a fire"}]', 'fight – fought – fought', '/faɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fig/fight/fight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 8, 'leader', 'người lãnh đạo; người dẫn đầu', 'noun', '[{"en":"She is a natural leader, and everyone listens to her.","vi":"Cô ấy là người lãnh đạo bẩm sinh, ai cũng nghe lời cô ấy."},{"en":"Our team leader holds a meeting every Monday morning.","vi":"Trưởng nhóm của chúng tôi họp vào mỗi sáng thứ Hai."},{"en":"After ten kilometers, he was still the leader of the race.","vi":"Sau mười cây số, anh ấy vẫn dẫn đầu cuộc đua."}]', '[{"phrase":"team leader"},{"phrase":"natural leader"},{"phrase":"world leader"},{"phrase":"group leader"}]', NULL, '/ˈliːdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leade/leader__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 9, 'fine', 'ổn; khỏe; tốt; tiền phạt', 'adjective', '[{"en":"I had a cold last week, but I''m fine now.","vi":"Tuần trước tôi bị cảm, nhưng giờ tôi khỏe rồi."},{"en":"Is it fine if I leave work a little early today?","vi":"Hôm nay tôi về sớm một chút có được không?"},{"en":"He had to pay a fine for parking in the wrong place.","vi":"Anh ấy phải nộp phạt vì đỗ xe sai chỗ."}]', '[{"phrase":"feel fine"},{"phrase":"that''s fine"},{"phrase":"fine weather"},{"phrase":"pay a fine"}]', NULL, '/faɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/fine_/fine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 10, 'street', 'đường phố; con phố', 'noun', '[{"en":"There is a small bakery at the end of our street.","vi":"Có một tiệm bánh nhỏ ở cuối con phố nhà chúng tôi."},{"en":"Look both ways before you cross the street.","vi":"Hãy nhìn cả hai phía trước khi băng qua đường."},{"en":"The streets were full of people during the festival.","vi":"Đường phố chật kín người trong dịp lễ hội."}]', '[{"phrase":"cross the street"},{"phrase":"main street"},{"phrase":"busy street"},{"phrase":"on the street"}]', NULL, '/striːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stree/street__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 11, 'former', 'cũ; trước đây', 'adjective', '[{"en":"I ran into my former teacher at the supermarket.","vi":"Tôi tình cờ gặp thầy giáo cũ ở siêu thị."},{"en":"Her former boss wrote her a great reference letter.","vi":"Sếp cũ của cô ấy đã viết cho cô ấy một thư giới thiệu rất tốt."},{"en":"This hotel is a former school building.","vi":"Khách sạn này trước đây là một tòa nhà trường học."}]', '[{"phrase":"former boss"},{"phrase":"former student"},{"phrase":"former home"},{"phrase":"former colleague"}]', 'the former … the latter: cái trước … cái sau', '/ˈfɔːrmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forme/former__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 12, 'contact', 'liên lạc; sự tiếp xúc', 'noun', '[{"en":"We lost contact after she moved to another city.","vi":"Chúng tôi mất liên lạc sau khi cô ấy chuyển đến thành phố khác."},{"en":"I still keep in contact with my old classmates.","vi":"Tôi vẫn giữ liên lạc với các bạn học cũ."},{"en":"Avoid contact with the eyes when using this cream.","vi":"Tránh để kem tiếp xúc với mắt khi sử dụng."}]', '[{"phrase":"keep in contact"},{"phrase":"lose contact"},{"phrase":"contact with"},{"phrase":"contact details"}]', 'contact sb (v): liên lạc với ai — không nói contact to sb', '/ˈkɑːntækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontact__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 13, 'particularly', 'đặc biệt là; nhất là', 'adverb', '[{"en":"I love fruit, particularly mangoes and bananas.","vi":"Tôi thích trái cây, nhất là xoài và chuối."},{"en":"The roads are particularly busy on Friday evenings.","vi":"Đường sá đặc biệt đông vào các tối thứ Sáu."},{"en":"I''m not particularly hungry, so I''ll just have tea.","vi":"Tôi không đói lắm nên tôi chỉ uống trà thôi."}]', '[{"phrase":"particularly important"},{"phrase":"particularly good"},{"phrase":"not particularly"}]', NULL, '/pərˈtɪkjələrli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/particularly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 14, 'wife', 'vợ', 'noun', '[{"en":"My wife and I met at university.","vi":"Vợ tôi và tôi gặp nhau ở trường đại học."},{"en":"He called his wife to say he would be late.","vi":"Anh ấy gọi cho vợ để báo là mình sẽ về muộn."},{"en":"Their wives are planning a trip together next month.","vi":"Vợ của họ đang lên kế hoạch đi du lịch cùng nhau vào tháng tới."}]', '[{"phrase":"husband and wife"},{"phrase":"my wife"},{"phrase":"his wife"}]', 'số nhiều: wives', '/waɪf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wif/wife_/wife__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 15, 'sport', 'thể thao; môn thể thao', 'noun', '[{"en":"Football is the most popular sport in my country.","vi":"Bóng đá là môn thể thao phổ biến nhất ở nước tôi."},{"en":"Do you play any sports after school?","vi":"Bạn có chơi môn thể thao nào sau giờ học không?"},{"en":"My brother is good at team sports like basketball.","vi":"Anh tôi giỏi các môn thể thao đồng đội như bóng rổ."}]', '[{"phrase":"play a sport"},{"phrase":"team sport"},{"phrase":"popular sport"},{"phrase":"sports club"}]', NULL, '/spɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/sport/sport__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 16, 'prepare', 'chuẩn bị', 'verb', '[{"en":"My mother is preparing dinner in the kitchen.","vi":"Mẹ tôi đang chuẩn bị bữa tối trong bếp."},{"en":"How are you preparing for your English exam?","vi":"Bạn đang chuẩn bị cho kỳ thi tiếng Anh như thế nào?"},{"en":"She prepared a short speech for the wedding.","vi":"Cô ấy đã chuẩn bị một bài phát biểu ngắn cho đám cưới."}]', '[{"phrase":"prepare for"},{"phrase":"prepare a meal"},{"phrase":"prepare dinner"},{"phrase":"prepare a report"}]', 'prepare for sth: chuẩn bị cho việc gì', '/prɪˈper/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prepa/prepare__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 17, 'discuss', 'thảo luận; bàn bạc', 'verb', '[{"en":"Let''s discuss this problem at the meeting tomorrow.","vi":"Hãy thảo luận vấn đề này trong cuộc họp ngày mai."},{"en":"We discussed where to go for our summer holiday.","vi":"Chúng tôi đã bàn bạc xem nên đi đâu vào kỳ nghỉ hè."},{"en":"I need to discuss my salary with my manager.","vi":"Tôi cần bàn về lương với quản lý của mình."}]', '[{"phrase":"discuss a problem"},{"phrase":"discuss the matter"},{"phrase":"discuss something with"}]', 'discuss sth (không có about)', '/dɪˈskʌs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discu/discuss__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 18, 'response', 'phản hồi; câu trả lời; phản ứng', 'noun', '[{"en":"I sent the email three days ago, but I haven''t had a response.","vi":"Tôi đã gửi email ba ngày trước nhưng vẫn chưa nhận được phản hồi."},{"en":"Her response to the question surprised everyone.","vi":"Câu trả lời của cô ấy cho câu hỏi khiến mọi người bất ngờ."},{"en":"The new product got a very positive response from customers.","vi":"Sản phẩm mới nhận được phản ứng rất tích cực từ khách hàng."}]', '[{"phrase":"in response to"},{"phrase":"positive response"},{"phrase":"get a response"},{"phrase":"quick response"}]', 'in response to: để đáp lại', '/rɪˈspɑːns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/response__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 19, 'voice', 'giọng nói; tiếng nói', 'noun', '[{"en":"She has a beautiful singing voice.","vi":"Cô ấy có giọng hát rất hay."},{"en":"Please lower your voice, the baby is sleeping.","vi":"Làm ơn nói nhỏ lại, em bé đang ngủ."},{"en":"I lost my voice after shouting at the football match.","vi":"Tôi bị mất giọng sau khi la hét ở trận bóng đá."}]', '[{"phrase":"lose your voice"},{"phrase":"raise your voice"},{"phrase":"lower your voice"},{"phrase":"loud voice"}]', NULL, '/vɔɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/voi/voice/voice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 20, 'piece', 'mẩu; miếng; mảnh', 'noun', '[{"en":"Can I have another piece of cake, please?","vi":"Cho tôi thêm một miếng bánh nữa được không?"},{"en":"Write your name on a piece of paper.","vi":"Hãy viết tên bạn lên một mẩu giấy."},{"en":"The glass fell off the table and broke into pieces.","vi":"Cái cốc rơi khỏi bàn và vỡ thành từng mảnh."}]', '[{"phrase":"a piece of paper"},{"phrase":"a piece of cake"},{"phrase":"a piece of advice"},{"phrase":"in pieces"}]', 'dùng để đếm danh từ không đếm được: a piece of advice', '/piːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pie/piece/piece__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 21, 'finish', 'hoàn thành; kết thúc', 'verb', '[{"en":"Have you finished your homework yet?","vi":"Con đã làm xong bài tập về nhà chưa?"},{"en":"The movie finished just before midnight.","vi":"Bộ phim kết thúc ngay trước nửa đêm."},{"en":"I need to finish this report before I go home.","vi":"Tôi cần hoàn thành bản báo cáo này trước khi về nhà."}]', '[{"phrase":"finish work"},{"phrase":"finish school"},{"phrase":"finish a meal"},{"phrase":"finish doing"}]', 'finish + V-ing: finish eating', '/ˈfɪnɪʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finis/finish__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 22, 'suppose', 'cho rằng; nghĩ là; giả sử', 'verb', '[{"en":"I suppose you''re tired after such a long trip.","vi":"Tôi nghĩ là bạn mệt sau một chuyến đi dài như vậy."},{"en":"Suppose you won a lot of money, what would you buy?","vi":"Giả sử bạn trúng được nhiều tiền, bạn sẽ mua gì?"},{"en":"You''re supposed to wear a helmet on a motorbike.","vi":"Bạn phải đội mũ bảo hiểm khi đi xe máy."}]', '[{"phrase":"I suppose so"},{"phrase":"be supposed to"},{"phrase":"I don''t suppose"}]', 'be supposed to do: phải / đáng lẽ phải làm gì', '/səˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/suppose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 23, 'apply', 'nộp đơn; áp dụng; bôi', 'verb', '[{"en":"She applied for a job at the new hotel.","vi":"Cô ấy đã nộp đơn xin việc tại khách sạn mới."},{"en":"These rules apply to all students in the school.","vi":"Những quy định này áp dụng cho tất cả học sinh trong trường."},{"en":"Apply the cream twice a day to the dry skin.","vi":"Bôi kem lên vùng da khô hai lần mỗi ngày."}]', '[{"phrase":"apply for a job"},{"phrase":"apply to"},{"phrase":"apply for a visa"},{"phrase":"apply cream"}]', 'apply for (xin) · apply to (áp dụng cho; nộp đơn vào)', '/əˈplaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/apply/apply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 24, 'president', 'tổng thống; chủ tịch', 'noun', '[{"en":"She was elected president of the student club.","vi":"Cô ấy được bầu làm chủ tịch câu lạc bộ sinh viên."},{"en":"The company president gave a speech at the party.","vi":"Chủ tịch công ty đã phát biểu tại bữa tiệc."},{"en":"In some countries, the president lives in a large official house.","vi":"Ở một số nước, tổng thống sống trong một dinh thự lớn."}]', '[{"phrase":"vice president"},{"phrase":"elected president"},{"phrase":"company president"}]', NULL, '/ˈprezɪdənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presi/president__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 25, 'fire', 'lửa; đám cháy; sa thải', 'noun', '[{"en":"We sat around the fire and told stories.","vi":"Chúng tôi ngồi quanh đống lửa và kể chuyện."},{"en":"Firefighters quickly put out the fire in the kitchen.","vi":"Lính cứu hỏa nhanh chóng dập tắt đám cháy trong bếp."},{"en":"He was fired for being late to work every day.","vi":"Anh ấy bị sa thải vì ngày nào cũng đi làm muộn."}]', '[{"phrase":"put out a fire"},{"phrase":"start a fire"},{"phrase":"catch fire"},{"phrase":"on fire"}]', 'fire (v) sa thải · catch fire: bắt lửa', '/ˈfaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/fire_/fire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 26, 'compare', 'so sánh', 'verb', '[{"en":"Always compare prices before you buy a new phone.","vi":"Hãy luôn so sánh giá trước khi mua điện thoại mới."},{"en":"Don''t compare yourself with other people.","vi":"Đừng so sánh bản thân với người khác."},{"en":"Compared to last year, this winter has been quite warm.","vi":"So với năm ngoái, mùa đông năm nay khá ấm."}]', '[{"phrase":"compare prices"},{"phrase":"compare with"},{"phrase":"compared to"},{"phrase":"compare notes"}]', 'compare A with/to B', '/kəmˈper/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/compare__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 27, 'court', 'tòa án; sân (quần vợt, bóng rổ)', 'noun', '[{"en":"The case will go to court next month.","vi":"Vụ việc sẽ được đưa ra tòa vào tháng tới."},{"en":"He had to appear in court as a witness.","vi":"Anh ấy phải ra tòa với tư cách nhân chứng."},{"en":"There are two tennis courts behind the hotel.","vi":"Có hai sân quần vợt phía sau khách sạn."}]', '[{"phrase":"go to court"},{"phrase":"in court"},{"phrase":"tennis court"},{"phrase":"basketball court"}]', NULL, '/kɔːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/court/court__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 28, 'police', 'cảnh sát; công an', 'noun', '[{"en":"Someone stole my bike, so I called the police.","vi":"Có người lấy trộm xe đạp của tôi nên tôi đã gọi cảnh sát."},{"en":"The police are looking for the lost child.","vi":"Cảnh sát đang tìm kiếm đứa trẻ bị lạc."},{"en":"A police officer helped the old man cross the road.","vi":"Một viên cảnh sát đã giúp cụ già băng qua đường."}]', '[{"phrase":"call the police"},{"phrase":"police officer"},{"phrase":"police station"},{"phrase":"tell the police"}]', 'police luôn đi với động từ số nhiều: the police are', '/pəˈliːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/police__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-04', 29, 'store', 'cửa hàng; cất giữ; lưu trữ', 'noun', '[{"en":"I''m going to the store to buy some milk.","vi":"Tôi ra cửa hàng mua ít sữa."},{"en":"The new department store opens on Saturday.","vi":"Cửa hàng bách hóa mới khai trương vào thứ Bảy."},{"en":"We store our winter clothes under the bed.","vi":"Chúng tôi cất quần áo mùa đông dưới gầm giường."}]', '[{"phrase":"grocery store"},{"phrase":"department store"},{"phrase":"store data"},{"phrase":"go to the store"}]', 'Mỹ: store · Anh: shop', '/stɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/store/store__us_1.mp3', NULL, NULL);
